************************************************************************
*                                                                      *
      subroutine twwbgreg(ncol,m,nr,mr,kr,tr,trEVENT)
*                                                                      *
*       wwbg tally                                                     *
*       last modified by Koji Niita on 2017/02/18                      *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              0 : end of batch                                        *
*              4 : source particle                                     *
*                                                                      *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
!$    use omp_lib
*-----------------------------------------------------------------------
      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   tr(nr,2,2)
      dimension   trEVENT(nr,2)           !OBINATA(2012.5.29): as Ct
      real(8),allocatable,save:: tr0(:,:) !OBINATA(2012.5.29): as C

      dimension ips(6)
      dimension facm(6)

      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

*-----------------------------------------------------------------------

      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall68/ itstp(itlmax), itmth(itlmax), rtvr0(itlmax),
     &                rtvx0(itlmax), rtvy0(itlmax), rtvz0(itlmax),
     &                rtvx1(itlmax), rtvy1(itlmax), rtvz1(itlmax)

      common /tall69/ itnms(itlmax), trmsh(itlmax,10),
     &                tzmsh(itlmax,10), tfmsh(itlmax,10),
     &                trmpo(itlmax,10), tzmpo(itlmax,10)

      common /trwwbg/ itrwwbg(4),rtrwwbg(13)

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.5.29): change tr(,,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ( nocas .gt. 1 .or. ncol .eq. 0 ) then

             tr(:,:,1) = tr(:,:,1) + trEVENT(:,:)
             tr(:,:,2) = tr(:,:,2) + trEVENT(:,:) ** 2

           end if

           trEVENT(:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.5.29): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(nr,2) )
             tr0(:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (twwbgreg_crit_ist1)
             tr0(:,:) = tr0(:,:) + trEVENT(:,:)
!$OMP END CRITICAL (twwbgreg_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,1) = tr(:,:,1) + tr0(:,:) / maxcas
             tr(:,:,2) = tr(:,:,2)
     &                     + ( tr0(:,:) / maxcas ) ** 2
             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

      if( ncol .ne. 4 ) return

*-----------------------------------------------------------------------
*        check position outside the region
*-----------------------------------------------------------------------

            call trnsxx(x(ibkx+no,ipomp+1),y(ibky+no,ipomp+1),
     &                  z(ibkz+no,ipomp+1),
     &                  xxa,yya,zza,itrwwbg(4))

*-----------------------------------------------------------------------

               nmesh = itnms(m)
               rfact = tfmsh(m,nmesh+1)

         do i = 1, nmesh

            radis = sqrt( xxa**2 + yya**2 )

            if( abs(zza) .le. tzmpo(m,i) .and.
     &          radis .le. trmpo(m,i) ) then

               rfact = tfmsh(m,i)
               exit

            end if

         end do

*-----------------------------------------------------------------------
*     check of region
*-----------------------------------------------------------------------

                  jj = 0

*-----------------------------------------------------------------------

      do 100 ii = 1, nr

*-----------------------------------------------------------------------

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .eq. 0 ) goto 100

               ir = ii

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

!OBINATA(2012.5.29): Ct = Ct + xi.wi
                     trEVENT(ir,1) = trEVENT(ir,1) + oldwt * rfact
                     trEVENT(ir,2) = trEVENT(ir,2) + oldwt

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------

      return
      end

************************************************************************
cKN 2017/02/18
*                                                                      *
      subroutine twwbgtet(ncol,m,nr,mr,kr,tr,trEVENT)
*                                                                      *
*       wwbg tally                                                     *
*       last modified by Koji Niita on 2017/02/18                      *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              0 : end of batch                                        *
*              4 : source particle                                     *
*                                                                      *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
!$    use omp_lib
*-----------------------------------------------------------------------
      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'
cFURUTA      include 'mmbank.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   tr(nr,2,2)
      dimension   trEVENT(nr,2)           !OBINATA(2012.5.29): as Ct
      real(8),allocatable,save:: tr0(:,:) !OBINATA(2012.5.29): as C

      dimension ips(6)
      dimension facm(6)

      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

*-----------------------------------------------------------------------

      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall68/ itstp(itlmax), itmth(itlmax), rtvr0(itlmax),
     &                rtvx0(itlmax), rtvy0(itlmax), rtvz0(itlmax),
     &                rtvx1(itlmax), rtvy1(itlmax), rtvz1(itlmax)

      common /tall69/ itnms(itlmax), trmsh(itlmax,10),
     &                tzmsh(itlmax,10), tfmsh(itlmax,10),
     &                trmpo(itlmax,10), tzmpo(itlmax,10)

      common /regdc/  idrg(kvlmax), idgr(kvmmax)
      common /trwwbg/ itrwwbg(4),rtrwwbg(13)

      integer iii0,kkk0
      common /itettal2/ iii0,kkk0
!$OMP THREADPRIVATE(/itettal2/)

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.5.29): change tr(,,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ( nocas .gt. 1 .or. ncol .eq. 0 ) then

             tr(:,:,1) = tr(:,:,1) + trEVENT(:,:)
             tr(:,:,2) = tr(:,:,2) + trEVENT(:,:) ** 2

           end if

           trEVENT(:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.5.29): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(nr,2) )
             tr0(:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (twwbgtet_crit_ist1)
             tr0(:,:) = tr0(:,:) + trEVENT(:,:)
!$OMP END CRITICAL (twwbgtet_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,1) = tr(:,:,1) + tr0(:,:) / maxcas
             tr(:,:,2) = tr(:,:,2)
     &                     + ( tr0(:,:) / maxcas ) ** 2
             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

      if( ncol .ne. 4 ) return

*-----------------------------------------------------------------------
*        check position outside the region
*-----------------------------------------------------------------------

!--- change NS 2020.04 del THREADPRIVATE
!            call trnsxx(x(ibkx+no),y(ibky+no),z(ibkz+no),
!     &                  xxa,yya,zza,itmtr(m,4))
            call trnsxx(x(ibkx+no,ipomp+1),y(ibky+no,ipomp+1),
     &                  z(ibkz+no,ipomp+1),
     &                  xxa,yya,zza,itrwwbg(4))
!--- end change NS 2020.04 del THREADPRIVATE

*-----------------------------------------------------------------------

               nmesh = itnms(m)
               rfact = tfmsh(m,nmesh+1)

         do i = 1, nmesh

            radis = sqrt( xxa**2 + yya**2 )

            if( abs(zza) .le. tzmpo(m,i) .and.
     &          radis .le. trmpo(m,i) ) then

               rfact = tfmsh(m,i)
               exit

            end if

         end do

*-----------------------------------------------------------------------
*     check region and tetra
*-----------------------------------------------------------------------

         jj = 0

         ic=idgr(iblz1)
         itet=kkk0-10000
         ihelem=iii0

         call ttetck(ic,mr,kr,itet,ihelem,ir,icc)

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

         if(icc.eq.1)then

!OBINATA(2012.5.29): Ct = Ct + xi.wi
                     trEVENT(ir,1) = trEVENT(ir,1) + oldwt * rfact
                     trEVENT(ir,2) = trEVENT(ir,2) + oldwt

         endif

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------

      return
      end

************************************************************************
*                                                                      *
      subroutine pwwbgreg(m,mc,kc,nr,mr,kr,tr,
     &                   vl,lr,nvl,ivl,rvl,igm,
     &                   nx,ny,nz,xm,ym,zm,igsh,idasa)
*                                                                      *
*       output the wwbg tally                                          *
*       last modified by Koji Niita on 2017/02/18                      *
*                                                                      *
************************************************************************
      use partmod ! frtati 2021/10/05
      use moddas_mesh

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

      common /stat / istdev, irestart, ireschk
      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      include 'param.inc'
      include 'ggsparam.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------
      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100
      common /tall31/ iterl(itlmax)

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall69/ itnms(itlmax), trmsh(itlmax,10),
     &                tzmsh(itlmax,10), tfmsh(itlmax,10),
     &                trmpo(itlmax,10), tzmpo(itlmax,10)

      common /tall29/ itrsh(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall49/ itglt(itlmax)

      character gfnam*100
      common /tall60/ itger(itlmax)

      common /istcut/ ist_cut, ist_bat
*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      common /tall67/ itstd(itlmax), rtstd(itlmax)

*-----------------------------------------------------------------------

      dimension   vl(nr)
      dimension   lr(nr)
      dimension   ivl(nvl)
      dimension   rvl(nvl)

      dimension   kc(mc)
      dimension   kr(mr)
      dimension   tr(nr,2,2)

      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   val(nr)

      integer,allocatable :: ixyz(:)

      dimension rmat(20)
      character dum1*10000
      character dum2*10000
      character dum3*10000
      character chdf(1000)*100
      dimension ildf(1000)
      character cblan*100

      character hsunit(14)*29
      data hsunit( 1) / '[WWB]                        '/

cfrtati 2021/10/05 6 -> itmxpt
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31

      common /rdouti/ nrdout, nrdi(100)

*-----------------------------------------------------------------------

      character cha*1
      data cha /"'"/

      character rpa*1
      data rpa /'}'/
      character yen*1
      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

*-----------------------------------------------------------------------
*        read from kc(mc)
*-----------------------------------------------------------------------

               call echrg2(mc,kc,dum1,lng1,icmb,igm)

*-----------------------------------------------------------------------
*        set mesh volume and name
*-----------------------------------------------------------------------

               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : nomalization for source
*-----------------------------------------------------------------------

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

               if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

                  c1 = 1.0d+0 / rsouin

               else

                  c1 = 0d0

               end if

            do 100 ir = 1, nr

               if( tr(ir,2,1) .gt. 0.d0 ) then

                  call calc_stdev(m,Xa,sigx,
     &            tr(ir,2,1),tr(ir,2,2),rsouin)

                  tr(ir,2,1) = Xa
                  tr(ir,2,2) = sigx

                  call calc_stdev(m,Xa,sigx,
     &            tr(ir,1,1),tr(ir,1,2),rsouin/tr(ir,2,1))

                  tr(ir,1,1) = Xa
                  tr(ir,1,2) = sigx

                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ir,1,1) .gt. cmax )
     &                        cmax = tr(ir,1,1)

                  if( tr(ir,1,1) .lt. cmin )
     &                        cmin = tr(ir,1,1)

               else

                  isdz = 1
                  tr(ir,1,1) = tfmsh(m,itnms(m)+1)
                  tr(ir,1,2) = 0.0

               end if

                  cmin = tfmsh(m,itnms(m)+1)

  100       continue


            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do 900 iax = 1, itfln(m)

         if( ( itall .eq. 2 .and. nobch .lt. maxbch )
     &        .or. itall .eq. 4 ) then

            call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &           nobch,maxbch,npe)

         else

            fname = ctfln(m,iax)

         end if

            iot = 31
            open(iot, file = fname, status = 'unknown' )

*-----------------------------------------------------------------------
            gfnam = ctfln(m,iax)
            igfmn = itfll(m,iax)
            igser = itger(m)

*-----------------------------------------------------------------------
*     input echo
*-----------------------------------------------------------------------

               call twbgech(iot,m,iax,1)

*-----------------------------------------------------------------------
*        wwbg axis (reg)
*-----------------------------------------------------------------------

         if( itaxs(m,iax) .eq. 1 ) then

               write(iot,'(/"#",78("-"))')

            np = itpan(m)
            ne = itenm(m)
            nt = ittnm(m)

            call wtpname(m,np,chp,chq)

      do ip = 1, np

         write(iot,'(/"[ WW Bias ]"/)')

                  write(iot,'("     mesh =  reg",11x,
     &            " # mesh type is region-wise"/)')

               if( nt .eq. 1 ) then
                  ien = ne
               else
                  ien = nt
               end if

            do i = 1, ien
               write(iot,'("set: c",i2,"[1.0]")') 70+i
            end do

               write(iot,'(/"   part = ",a8)') chq(ip)

                  if( nt .eq. 1 ) then
                     write(iot,'("    eng =",i3)') ne
                  else
                     write(iot,'("    tim =",i3)') nt
                  end if

                     ienm = ( ien - 1 ) / 5 + 1

                        k   = 0

                  do i = 1, ien

                        k = k + 1

                     if( nt .eq. 1 ) then

                        rmat(k) = das_iterg(iterg(m)+i)

                     else

                        rmat(k) = das_ittrg(ittrg(m)+i)

                     end if

                        if( k / 5 * 5 .eq. k .or. k .eq. ien ) then

                           write(iot,'(6x,5(1p1e14.5))')
     &                          ( rmat(l),l = 1, k )

                           k = 0

                        end if

                  end do

*-----------------------------------------------------------------------
               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)

*-----------------------------------------------------------------------

                  lngmax = 0
                  j = 0

               do ir = 1, nr

                  call echrg3(j,mr,kr,dum2,lng1,icmb,igm)

                  if( lng1 .gt. lngmax ) lngmax = lng1

               end do

                  lblk = lngmax
                  dum1(1:6) = '   reg'

                do i = 1, lblk
                  dum1(i+6:i+6) = ' '
                end do

                  lbin = lblk + 6

*-----------------------------------------------------------------------

            do ll = 1, ienm

               li = ( ll - 1 ) * 5 + 1
               lf = min( li + 4, ien )
               ld = lf - li + 1

               lbb = lbin

               do jj = 1, ld

                     nn = li + jj - 1

                  if( nn .lt. 10 ) then

                     dum1(lbb+1:lbb+10) = '       wwb'
                     write(dum1(lbb+11:lbb+11),'(i1)') nn
                     dum1(lbb+12:lbb+19) = '        '

                  else

                     dum1(lbb+1:lbb+10) = '       wwb'
                     write(dum1(lbb+11:lbb+12),'(i2)') nn
                     dum1(lbb+13:lbb+19) = '       '

                  end if

                     lbb = lbb + 19

               end do

                     write(iot,'(/600a1)') (dum1(i:i),i=1,lbb)

*-----------------------------------------------------------------------

                     j = 0

               do ir = 1, nr

                     iovoid = 0
                  if( nrdout .gt. 0 ) then
                     do km = 1, nrdout
                        if( lr(ir) .eq. nrdi(km) ) iovoid = 1
                     end do
                  end if

                     call echrg3(j,mr,kr,dum3,lng1,icmb,igm)

                     dum2(1:3) = '   '

                  do i = 1, lng1
                     dum2(i+3:i+3) = dum3(i:i)
                  end do

                     lngb = lngmax - lng1

                  do i = 1, lngb + 2
                     dum2(i+lng1+3:i+lng1+3) = ' '
                  end do

                     lni = lngb + lng1 + 3 + 2 + 1

                  do jj = 1, ld

                     nn = li + jj - 1

                     wwt = tr(ir,1,1)

                        dum2(lni:lni+1) = '('
                        lni = lni + 1

                        write(dum2(lni:lni+11),'(1p1e11.5)') wwt
                        lni = lni + 11

                        dum2(lni:lni+2) = '*c'
                        lni = lni + 2
                        write(dum2(lni:lni+2),'(i2)') 70+nn
                        lni = lni + 2
                        dum2(lni:lni+1) = ')'
                        lni = lni + 1
                        dum2(lni:lni+2) = '  '
                        lni = lni + 2

                  end do

                     if( iovoid .eq. 0 ) then
                        write(iot,'(600a1)') (dum2(i:i),i=1,lni)
                     end if

               end do

            end do

*-----------------------------------------------------------------------

      end do

*-----------------------------------------------------------------------
*        xy axis (matrix)
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 2 ) then

*-----------------------------------------------------------------------

               inum = 0

            do iz = 1, nz

               zval = ( zm(iz) + zm(iz+1) ) / 2.0d0

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

                  write(iot,'("#   no. =",i3,3x,
     &            "iz  =",i3/
     &            "#   z = ",1p1e13.4)')
     &                     inum, iz, zval

*-----------------------------------------------------------------------

                     write(iot,'(/a1,"no. =",i3,
     &                     ",  iz =",i3,a1)')
     &                     cha, inum, iz, cha

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdl: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdr: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'(/"x: x [cm]")')

               else

                  write(iot,'(/"x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: y [cm]")')

               else

                  write(iot,'( "y: ",200a1)')
