      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /egs5cmn10/denstepold,denstepnew,deinit
      real*8            denstepold,denstepnew,deinit
!$OMP THREADPRIVATE(/egs5cmn10/)

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------

      common /spred/ nspred, nwsprd, nedisp, itstep, ndedx

      common /  tscmsg   / ktsc(kvlmax), mntsc, ntsc(kvlmax)
      common /  tscreg   / ntscell(kvlmax)
      common / etsminmax / etsmin, etsmax

! T.Sato 2024/03/18 weighted history counter ID
      common /tall92/ ichnum(itlmax),chbias(itlmax),pedest(itlmax)
     &               ,ictnum(itlmax),ctbias(itlmax),ictidx(itlmax)
*-----------------------------------------------------------------------

      icf(ix,iy,iz) = ix + ( iy - 1 ) * nx + ( iz - 1 ) * nx * ny

*-----------------------------------------------------------------------

         small = parz(28) * 10.d0
         rng1 = 0.0d0 !FURUTA

*-----------------------------------------------------------------------

      if (istdev .eq. 2) then

        call readitrminmax7(itrmin,itrmax,(/ np,ne,nt,nx,ny,nz,nm/),
     &                      mnp,mne,mnt,mnx,mny,mnz,mnm,
     &                      mxp,mxe,mxt,mxx,mxy,mxz,mxm)

      endif

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*OBINATA(2012.6.13)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then
             do im = mnm,mxm
             do iz = mnz,mxz
             do iy = mny,mxy
             do ix = mnx,mxx
               ixyz = icf(ix,iy,iz)
               tr(:,mne:mxe,:,ixyz,im,1)
     &           = tr(:,mne:mxe,:,ixyz,im,1)
     &           + trEVENT(:,mne:mxe,:,ixyz,im,1)
               tr(:,mne:mxe,:,ixyz,im,2)
     &           = tr(:,mne:mxe,:,ixyz,im,2)
     &           + trEVENT(:,mne:mxe,:,ixyz,im,1) ** 2

               if(ichnum(m).ne.0) then ! history counter biased T.Sato 2024/03/21

                tr(:,mne:mxe,:,ixyz,im,3)
     &           = tr(:,mne:mxe,:,ixyz,im,3)
     &           + trEVENT(:,mne:mxe,:,ixyz,im,ict)*ncntmx(ichnum(m))
                tr(:,mne:mxe,:,ixyz,im,4)
     &           = tr(:,mne:mxe,:,ixyz,im,4)
     &        + (trEVENT(:,mne:mxe,:,ixyz,im,ict)*ncntmx(ichnum(m)))**2

               elseif(ictnum(m).ne.0) then ! only counter biased

                tr(:,mne:mxe,:,ixyz,im,3)
     &           = tr(:,mne:mxe,:,ixyz,im,3)
     &           + trEVENT(:,mne:mxe,:,ixyz,im,ict)
                tr(:,mne:mxe,:,ixyz,im,4)
     &           = tr(:,mne:mxe,:,ixyz,im,4)
     &           + trEVENT(:,mne:mxe,:,ixyz,im,ict)**2

               endif
             enddo
             enddo
             enddo
             enddo

! sumover
             call twwgxyz_sumover(m,1,
     &                   np,  ne, nt,  nx, ny, nz, nm, trEVENT)


           end if

           do im = mnm,mxm
           do iz = mnz,mxz
           do iy = mny,mxy
           do ix = mnx,mxx
             trEVENT(:,mne:mxe,:,icf(ix,iy,iz),im,:) = 0
           enddo
           enddo
           enddo
           enddo

           call resetitrminmax(itrmin,itrmax,7,(/np,ne,nt,nx,ny,nz,nm/))

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*OBINATA(2012.6.13)
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nt,nx*ny*nz,nm,ict) )
             tr0(:,:,:,:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (ttracxyz_crit)
             tr0(:,:,:,:,:,:) = tr0(:,:,:,:,:,:) + trEVENT(:,:,:,:,:,:)
!$OMP END CRITICAL (ttracxyz_crit)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,:,:,1) = tr(:,:,:,:,:,1)
     &                       + tr0(:,:,:,:,:,1) / maxcas
             tr(:,:,:,:,:,2) = tr(:,:,:,:,:,2)
     &                     + ( tr0(:,:,:,:,:,1) / maxcas ) ** 2
! sumover
             call twwgxyz_sumover(m,maxcas,
     &                   np,  ne, nt,  nx, ny, nz, nm, tr0)

        if(ict.eq.2) then
             tr(:,:,:,:,:,3) = tr(:,:,:,:,:,3)
     &                       + tr0(:,:,:,:,:,ict) / maxcas
             tr(:,:,:,:,:,4) = tr(:,:,:,:,:,4)
     &                     + ( tr0(:,:,:,:,:,ict) / maxcas ) ** 2
        endif

             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

*-----------------------------------------------------------------------

      if( iMeVperu.eq.1 .and. ityp.ge.15 .and. ityp.le.19 ) then
           ebm = ktyp - ktyp / 1000000 * 1000000
      else
           ebm = 1.d0
      end if

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                   return

               end if

            end do

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        check of particles
*-----------------------------------------------------------------------

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 ) return

*-----------------------------------------------------------------------
cc H.Iwase 2015/4/2 for electrons
cc                  change the step energy to coutinuous energy
*-----------------------------------------------------------------------

                mat1 = 0
            if( mntsc .gt. 0 .and.
     &          ntscell( idgr(iblz(ibkblz+no,ipomp+1)) ) .ne. 0 .and.
     &        ( ityp .eq. 12 .or. ityp .eq. 13 ) .and.
     &        ( e(ibke+no,ipomp+1) .le. etsmax .and.
     &          e(ibke+no,ipomp+1) .ge. etsmin ) )
     &          mat1 = ntscell( idgr(iblz(ibkblz+no,ipomp+1)) )

      if( ( ityp.eq.12 .or. ityp.eq.13 ) .and.
     .   (( mat1 .eq. 0 )                .or.
     .    ( mat1 .ne. 0 .and. e(ibke+no,ipomp+1) .gt. etsmax ))  )then
      else
           deinit     = 0.d0
           denstepold = 0.d0
           denstepnew = 0.d0
      endif

      if( ityp.eq.12 .or. ityp.eq.13 )then

         e1 =  e(ibke  +no,ipomp+1) - deinit  + denstepold
         e2 = ec(ibkec +no,ipomp+1) - deinit  + denstepnew

         if( e1 .lt. eb(1)    ) return
         if( e2 .ge. eb(ne+1) ) return

         tparti = abs(t(ibkt+no,ipomp+1))
         tpartf = abs(tc(ibktc+no,ipomp+1))
         if( tparti .ge. tb(nt+1) ) return
         if( tpartf .lt. tb(1) ) return

          e(ibke +no,ipomp+1) = e1
         ec(ibkec+no,ipomp+1) = e2

      endif
*-----------------------------------------------------------------------
*        check of energy
*-----------------------------------------------------------------------

            if( e(ibke+no,ipomp+1)   .lt. eb(1)*ebm ) goto 999
            if( ec(ibkec+no,ipomp+1) .ge. eb(ne+1)*ebm ) goto 999

*-----------------------------------------------------------------------
*           check of time
*-----------------------------------------------------------------------

               tparti = abs(t(ibkt+no,ipomp+1))
               tpartf = abs(tc(ibktc+no,ipomp+1))

               if( tparti .ge. tb(nt+1) ) goto 999
               if( tpartf .lt. tb(1) ) goto 999

*-----------------------------------------------------------------------

            icli = idgr(iblz1)

*-----------------------------------------------------------------------
*        transform positions
*-----------------------------------------------------------------------

            call trnsxx(x(ibkx+no,ipomp+1),y(ibky+no,ipomp+1),
     &                  z(ibkz+no,ipomp+1),
     &                  xxa,yya,zza,itmtr(m,4))

            call trnsxx(xc(ibkxc+no,ipomp+1),yc(ibkyc+no,ipomp+1),
     &                  zc(ibkzc+no,ipomp+1),
     &                  xxc,yyc,zzc,itmtr(m,4))

*-----------------------------------------------------------------------
*        check position : out of rainge
*-----------------------------------------------------------------------

            if( xxa-small .lt. xm(1) .and.
     &          xxc-small .lt. xm(1) ) goto 999

            if( yya-small .lt. ym(1) .and.
     &          yyc-small .lt. ym(1) ) goto 999

            if( zza-small .lt. zm(1) .and.
     &          zzc-small .lt. zm(1) ) goto 999

            if( xxa+small .ge. xm(nx+1) .and.
     &          xxc+small .ge. xm(nx+1) ) goto 999

            if( yya+small .ge. ym(ny+1) .and.
     &          yyc+small .ge. ym(ny+1) ) goto 999

            if( zza+small .ge. zm(nz+1) .and.
     &          zzc+small .ge. zm(nz+1) ) goto 999

*-----------------------------------------------------------------------
*        distance and unit vector ud(i)
*-----------------------------------------------------------------------

            dis = ( xxc - xxa )**2
     &          + ( yyc - yya )**2
     &          + ( zzc - zza )**2

            if( dis .le. small**2 ) goto 999

            dis = sqrt(dis)

            ud(1) = ( xxc - xxa ) / dis
            ud(2) = ( yyc - yya ) / dis
            ud(3) = ( zzc - zza ) / dis

*-----------------------------------------------------------------------
*     initial position, energy and initial range
*-----------------------------------------------------------------------

            tot = 0.0d0
            tpt = tparti

            se  = e(ibke+no,ipomp+1)
            xpp = xxa
            ypp = yya
            zpp = zza

            if( jtyp .ne. 0 .and. mat .gt. 0 )
     &          call rainge(se,rng,mat,ityp,ktyp,jtyp,rtyp)

*-----------------------------------------------------------------------
*     initial xyz position
*-----------------------------------------------------------------------

               ixm = 0
               ixc = 0

            if( ud(1) .gt. 0.0d0 ) ixk =  1
            if( ud(1) .eq. 0.0d0 ) ixk =  0
            if( ud(1) .lt. 0.0d0 ) ixk = -1

            if( ixk .ge. 0 ) then

               do i = 1, nx + 1
                  if( xm(i) .gt. xpp + small ) then
                         ixm = i - 1
                         ixc = i - 1
                         goto 32
                  end if
               end do

            else

               ixm = nx + 2
               ixc = nx + 1

               do i = 1, nx + 1
                  if( xm(i) .ge. xpp - small ) then
                         ixm = i
                         ixc = i - 1
                         goto 32
                  end if
               end do

            end if

   32       continue

*-----------------------------------------------------------------------

               iym = 0
               iyc = 0

            if( ud(2) .gt. 0.0d0 ) iyk =  1
            if( ud(2) .eq. 0.0d0 ) iyk =  0
            if( ud(2) .lt. 0.0d0 ) iyk = -1

            if( iyk .ge. 0 ) then

               do i = 1, ny + 1
                  if( ym(i) .gt. ypp + small ) then
                         iym = i - 1
                         iyc = i - 1
                         goto 35
                  end if
               end do

            else

               iym = ny + 2
               iyc = ny + 1

               do i = 1, ny + 1
                  if( ym(i) .ge. ypp - small ) then
                         iym = i
                         iyc = i - 1
                         goto 35
                  end if
               end do

            end if

   35       continue

*-----------------------------------------------------------------------

               izm = 0
               izc = 0

            if( ud(3) .gt. 0.0d0 ) izk =  1
            if( ud(3) .eq. 0.0d0 ) izk =  0
            if( ud(3) .lt. 0.0d0 ) izk = -1

            if( izk .ge. 0 ) then

               do i = 1, nz + 1
                  if( zm(i) .gt. zpp + small ) then
                         izm = i - 1
                         izc = i - 1
                         goto 38
                  end if
               end do

            else

               izm = nz + 2
               izc = nz + 1

               do i = 1, nz + 1
                  if( zm(i) .ge. zpp - small ) then
                         izm = i
                         izc = i - 1
                         goto 38
                  end if
               end do

            end if

   38       continue

*-----------------------------------------------------------------------
*     loop for finding mesh and booking upto total distance
*-----------------------------------------------------------------------

      iloop=0 ! T.Sato 2021/11/06 avoid infinite loop
      do 50 while ( .not. tot .ge. dis )
       iloop=iloop+1
       if(iloop.gt.1000000) then
        write(ErrCha,'("warning: iloop is too large")')
        ErrID = 'L:11905/R:twwgxyz/F:talls07.f'
        call ErrWrite(ErrID,ErrCha)
        exit
       endif

*-----------------------------------------------------------------------
*     calculation is finished
*-----------------------------------------------------------------------


*-----------------------------------------------------------------------
*        dx,dy,dz : distance to the nearest xyz mesh
*-----------------------------------------------------------------------

            dx = dmax
            dy = dmax
            dz = dmax

         if( ixk .ne. 0 ) then
            if( ixm + ixk .ge. 1 .and.
     &         ixm + ixk .le. nx + 1 ) then

               dx = abs( ( xm(ixm+ixk) - xpp ) / ud(1) )

            end if
         end if

         if( iyk .ne. 0 ) then
            if( iym + iyk .ge. 1 .and.
     &          iym + iyk .le. ny + 1 ) then

               dy = abs( ( ym(iym+iyk) - ypp ) / ud(2) )

            end if
         end if

         if( izk .ne. 0 ) then
            if( izm + izk .ge. 1 .and.
     &          izm + izk .le. nz + 1 ) then

               dz = abs( ( zm(izm+izk) - zpp ) / ud(3) )

            end if
         end if

*-----------------------------------------------------------------------
*        which boundary is the nearlist
*-----------------------------------------------------------------------

               dd = dx
               jj = 1

            if( dy .lt. dd ) then

               dd = dy
               jj = 2

            end if

            if( dz .lt. dd ) then

               dd = dz
               jj = 3

            end if

               tt = dd

            if( dd .gt. dmax0 ) return

*-----------------------------------------------------------------------
*        recalculate rng for ncol = 11 and nedisp
*-----------------------------------------------------------------------

            if( mat .gt. 0 .and. jtyp .ne. 0 .and. nedisp .ne. 0 .and.
     &           (  ityp .ne. 12 .and. ityp .ne. 13 ) ) then


               call rainge(se,rng,mat,ityp,ktyp,jtyp,rtyp)

               if( ncol .eq. 11 )  dis = tot + rng

            end if

*-----------------------------------------------------------------------
*        propagate position upto the boundary or the final point
*-----------------------------------------------------------------------

            if( tot + dd .ge. dis - small ) then

               dd  = dis - tot
               tot = dis
               xpp = xxc
               ypp = yyc
               zpp = zzc

            else

               tot = tot + dd
               xpp = xpp + tt * ud(1)
               ypp = ypp + tt * ud(2)
               zpp = zpp + tt * ud(3)

            end if

*-----------------------------------------------------------------------
*        final energy ee and range rng1
*-----------------------------------------------------------------------

            if( jtyp .ne. 0 .and. mat .gt. 0 ) then

               delt = dd

               call ecol(ee,delt,se,rng,
     &                   mat,ityp,ktyp,jtyp,rtyp)

               rng1 = max( 0.0d0, rng - delt )

               ee = max( 0.0d0, ee )
               ee = min( se, ee )

            else

               ee = se

            end if

*-----------------------------------------------------------------------
*        time evolution
*-----------------------------------------------------------------------

               ekin = ( se + ee ) / 2.0
               dist = dd
               timd = 0.0

               if( ekin .gt. 0.1 .or. rtyp .eq. 0.0d0 ) then

                  timd = dist * ( ekin + rtyp )
     &                 / sqrt( ekin * ( ekin + 2.0 * rtyp ) )
     &                 / rlit

               else if( ekin .gt. 0.0 ) then

                  timd = dist * sqrt( rtyp / 2.0 / ekin ) / rlit

               end if

                  tpc = tpt
                  tpt = tpt + timd

*-----------------------------------------------------------------------
*        booking
*-----------------------------------------------------------------------

         if( ixc .ge. 1 .and. ixc .lt. nx + 1 .and.
     &       iyc .ge. 1 .and. iyc .lt. ny + 1 .and.
     &       izc .ge. 1 .and. izc .lt. nz + 1 ) then

*-----------------------------------------------------------------------
*           initial and final energy cell
*-----------------------------------------------------------------------

            do i = 1, ne

               if( se .ge. eb(i)*ebm .and.
     &             se .lt. eb(i+1)*ebm ) goto 30

            end do

   30          ie1 = min( i, ne )

            do i = ne, 1, -1

               if( ee .ge. eb(i)*ebm .and.
     &             ee .lt. eb(i+1)*ebm ) goto 40

            end do

   40          ie2 = max( i, 1 )

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

                  rrl = dd
                  rrr = dd
                  rrt = 0.0d0

            if( jtyp .ne. 0 .and. mat .gt. 0 ) then

               if( se .gt. eb(ne+1)*ebm ) then

                  call rainge(eb(ne+1)*ebm,rngm,mat,ityp,ktyp,jtyp,rtyp)

                  rrr = max( 0.0d0, rrr - ( rng - rngm ) )
                  rrt = rrt + rng -rngm

                     dst = max( 0.0d0, rng - rngm )
                     erg = ( se + eb(ne+1)*ebm ) / 2.0
                     tmd = 0.0d0

                  if( erg .gt. 0.1 .or. rtyp .eq. 0.0d0 ) then

                     tmd = dst * ( erg + rtyp )
     &                   / sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                   / rlit

                  else if( erg .gt. 0.0 ) then

                     tmd = dst * sqrt( rtyp / 2.0 / erg ) / rlit

                  end if

                     tpc = tpc + tmd

               end if

            end if

                  tpi = tpc

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 270 ie = ie1, ie2, -1

               emie = max( ee, eb(ie)*ebm )
               emiu = min( se, eb(ie+1)*ebm )
               erg  = ( emiu + emie ) / 2.0

               call fmfac(m,icli,erg,oldwt,facm)

               if( jtyp .ne. 0 .and. mat .gt. 0 ) then

                  call rainge(emie,rng2,mat,ityp,ktyp,jtyp,rtyp)

                  rng2 = max( 0.0d0, rng2 - rng1 )
                  rrl  = max( 0.0d0, rrr  - rng2 )

*-----------------------------------------------------------------------

                  rrt  = rrt + rrl

                  if( rrt .gt. dd ) then

                     rrl = rrl + ( dd - rrt )
                     rrt = dd

                  else if( ie .eq. ie2 .and. ee .gt. eb(ie) ) then

                     rrl = rrl + ( dd - rrt )

                  end if

*-----------------------------------------------------------------------

               end if

*-----------------------------------------------------------------------
*              initial and final time
*-----------------------------------------------------------------------

               dst = rrl
               tmd = 0.0d0
               CC  = 0.0d0

               if( erg .gt. 0.1 .or. rtyp .eq. 0.0d0 ) then

                  tmd = dst * ( erg + rtyp )
     &                / sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                / rlit
                  CC  = 1.d0 / ( erg + rtyp )
     &                * sqrt( erg * ( erg + 2.0 * rtyp ) )
     &                * rlit

               else if( erg .gt. 0.0 ) then

                  tmd = dst * sqrt( rtyp / 2.0 / erg ) / rlit
                  CC = 1.d0 / sqrt( rtyp / 2.0 / erg ) * rlit

               end if

               tpf = tpi + tmd

               do 271 it = 1, nt

                  if( tpf .lt. tb(it) .or. tpi .ge. tb(it+1) ) goto 271

                  tin = max( tpi, tb(it) )
                  tfn = min( tpf, tb(it+1) )
                  tmd = max( 0.0d0, tfn - tin )

                  dst = tmd * CC

*-----------------------------------------------------------------------

                  tlv = oldwt * dst

               do im = 1, nm
               do ip = 1, ipn

!OBINATA(2012.6.13): Ct = Ct + xi.wi
                  trEVENT(ips(ip),ie,it,icf(ixc,iyc,izc),im,1) =
     &            trEVENT(ips(ip),ie,it,icf(ixc,iyc,izc),im,1)
     &            + tlv * facm(im)
                if(ict.eq.2) then
                 if(ictnum(m).ne.0) then ! counter bias mode
                  trEVENT(ips(ip),ie,it,icf(ixc,iyc,izc),im,2) =
     &            trEVENT(ips(ip),ie,it,icf(ixc,iyc,izc),im,2)
     &            + dst * ncnt(ibknct+ictnum(m),no,ipomp+1) ! Monte Carlo fluence without multiplier
                 else ! only history counter is defined
                  trEVENT(ips(ip),ie,it,icf(ixc,iyc,izc),im,2) =
     &            trEVENT(ips(ip),ie,it,icf(ixc,iyc,izc),im,2)
     &            + dst ! Monte Carlo fluence without multiplier
                 endif
                endif

               end do
               end do

*-----------------------------------------------------------------------

  271          continue

               rrr = rrr - rrl
               tpi = tpf

  270       continue

         if (istdev .eq. 2) then

cKN 2015/12/01 ??
           call setitrmin(itrmin,2,7,(/ie2, 1,ixc,iyc,izc, 1/))
           call setitrmax(itrmax,2,7,(/ie1,it,ixc,iyc,izc,nm/))

         endif

*-----------------------------------------------------------------------

         end if

*-----------------------------------------------------------------------
*     next position
*-----------------------------------------------------------------------

            if( jj .eq. 1 ) then

               ixm = ixm + ixk
               ixc = ixc + ixk

            else if( jj .eq. 2 ) then

               iym = iym + iyk
               iyc = iyc + iyk

            else if( jj .eq. 3 ) then

               izm = izm + izk
               izc = izc + izk

            end if

               se  = ee
               rng = rng1

*-----------------------------------------------------------------------

  50  continue

*-----------------------------------------------------------------------
cc H.Iwase 2015/4/2 for electrons
cc                  change the continuous energy back to the step energy

  999 if( ityp.eq.12 .or. ityp.eq.13 )then

          e(ibke +no,ipomp+1) =  e(ibke +no,ipomp+1) +
     &                                  deinit  - denstepold
         ec(ibkec+no,ipomp+1) = ec(ibkec+no,ipomp+1) +
     &                                  deinit  - denstepnew


      endif


*-----------------------------------------------------------------------

      end


************************************************************************
*                                                                      *
      subroutine pwwgxyz(m,np,nl,lt,
     &                   nx,ny,nz,ne,nm,nt,mftal,xm,ym,zm,eb,tb,tr,
     &                   igsh,idasa)
*                                                                      *
*       output xyz scoring mesh track length tally                     *
*       last modified by K.Niita on 2018/01/08                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

      use moddas_mesh !FURUTA20221108

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

      common /stat / istdev, irestart, ireschk

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall21/ rtfac(itlmax)
      common /tall28/ itgsh(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall45/ itmlp(itlmax), itmln(itlmax,6), itmst(itlmax),
     &                itmli(itlmax,6), rtmme(itlmax,6), itmnt(itlmax,6),
     &                itmpn(itlmax,6), itmpt(itlmax,6,6,2)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall49/ itglt(itlmax)

      common /istcut/ ist_cut, ist_bat
*-----------------------------------------------------------------------

      common /tcntl/  icntl, inucr

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   eb(ne+1)
      dimension   ew(ne)
      dimension   tb(nt+1)
      dimension   tw(nt)
      dimension   tr(np,ne,nt,nx*ny*nz,nm,mftal) ! S.H. 2024.3.21

      integer,allocatable :: ixyz(:)

*-----------------------------------------------------------------------

      dimension   emm(np,ne,3)
      dimension   tmm(np,nt,3)

      dimension rmat(20)
      character dum1*10000
      character dum2*10000
      character dum3*10000

      integer           iMeVperu
      common /cMeVperu/ iMeVperu

! T.Sato 2024/03/18 weighted history counter ID
      common /tall92/ ichnum(itlmax),chbias(itlmax),pedest(itlmax)
     &               ,ictnum(itlmax),ctbias(itlmax),ictidx(itlmax)

      common /tall94/ normwwg(itlmax),wwmax(itlmax),ichplane(itlmax) ! twwg normalization parameter
     &               ,elowthre(itlmax),elowbias(itlmax)  ! T.Sato 2025/01/04

      dimension dimtmp(nx*ny*nz*nm) ! T.Sato 2024/05/28, temporary dimension for finding emm
*-----------------------------------------------------------------------

      dimension tott(np,2) ! frtati 2021/10/05 6 -> np

      character hsunit(14)*29
      data hsunit( 1) / '[1/cm^2/source]              '/

      character cha*1
      data cha /"'"/

cfrtati 2021/10/05 chl, chm moved to partmod

      character dc2*4

cfrtati 2021/10/05 6 -> itmxpt
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31
      character chqfull*200 ! T.Sato 2024/05/28

*-----------------------------------------------------------------------

      character rpa*1
      data rpa /'}'/
      character yen*1

      real(8),allocatable :: vl_x(:,:),vl_y(:,:),vl_z(:,:)

      include 'samepage_include/samepage000.inc'

*-----------------------------------------------------------------------

      icf(ix,iy,iz) = ix + ( iy - 1 ) * nx + ( iz - 1 ) * nx * ny

*-----------------------------------------------------------------------
*        set mesh volume ( unit = 4, 14 ; vol = 1.0 )
*-----------------------------------------------------------------------

         vl(ix,iy,iz) =  vls(nl,lt,itmcn(m),itvm(m),itmtr(m,4),
     &                       xm(ix),xm(ix+1),
     &                       ym(iy),ym(iy+1),
     &                       zm(iz),zm(iz+1))

*-----------------------------------------------------------------------
      include 'samepage_include/samepage001.inc'

      allocate (vl_x(ny,nz),vl_y(nx,nz),vl_z(nx,ny))
      vl_x(:,:) = 0.0d0
      vl_y(:,:) = 0.0d0
      vl_z(:,:) = 0.0d0
      do iz= 1, nz
         do iy= 1, ny
           do ix = 1,nx
             vl_x(iy,iz) = vl_x(iy,iz) + vl(ix,iy,iz)
             vl_y(ix,iz) = vl_y(ix,iz) + vl(ix,iy,iz)
             vl_z(ix,iy) = vl_z(ix,iy) + vl(ix,iy,iz)
           enddo
         enddo
      enddo

      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

*-----------------------------------------------------------------------
      ioe = 1

      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*     for igshow
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

            npg = np
            neg = ne
            ntg = nt

         else

            npg = 1
            neg = 1
            ntg = 1

         end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*           itunt(m) = 1: /cm^2/source
*-----------------------------------------------------------------------

               do i = 1, ne

                  ew(i) = 1.d+0

               end do
               ew_sum = 1.0d0

*-----------------------------------------------------------------------
*           itunt(m) = 1
*-----------------------------------------------------------------------

               do i = 1, nt

                  tw(i) = 1.d+0

               end do
               tw_sum = 1.0d0

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : nomalization for source
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

               c1 = 1.0d+0 / rsouin

            do 100 ip = 1, np
            do 100 it = 1, nt
            do 100 ie = 1, ne

             if( nt .eq. 1 ) then

             idimsize=0

              emm(ip,ie,1) = 1.e+33
              emm(ip,ie,2) = 0.0
              emm(ip,ie,3) = 0.0

             else

              tmm(ip,it,1) = 1.e+33
              tmm(ip,it,2) = 0.0
              tmm(ip,it,3) = 0.0

             end if

             do 110 im = 1, nm

             do 101 iz = 1, nz
             do 101 iy = 1, ny
             do 101 ix = 1, nx

               if( tr(ip,ie,it,icf(ix,iy,iz),im,1) .gt. 0.d0 ) then

                  call calc_stdev(m,Xa,sigx,
     &                            tr(ip,ie,it,icf(ix,iy,iz),im,1),
     &                            tr(ip,ie,it,icf(ix,iy,iz),im,2),
     &                            rtfac(m)/vl(ix,iy,iz)/ew(ie)/tw(it))

                  tr(ip,ie,it,icf(ix,iy,iz),im,1) = Xa
                  tr(ip,ie,it,icf(ix,iy,iz),im,2) = sigx
                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ip,ie,it,icf(ix,iy,iz),im,1) .gt. cmax )
     &                     cmax = tr(ip,ie,it,icf(ix,iy,iz),im,1)

                  if( tr(ip,ie,it,icf(ix,iy,iz),im,1) .lt. cmin )
     &                     cmin = tr(ip,ie,it,icf(ix,iy,iz),im,1)

                  if(ichnum(m).eq.0.and.ictnum(m).eq.0) then ! determine emm, tmm, T.Sato 2024/03/21 for non-biased case
                   idimsize=idimsize+1
                   dimtmp(idimsize)=tr(ip,ie,it,icf(ix,iy,iz),im,1)
                  endif

               else

                  isdz = 1
                  tr(ip,ie,it,icf(ix,iy,iz),im,2) = 0.d+0

               end if

               if(ichnum(m).ne.0.or.ictnum(m).ne.0) then ! history counter weighted, T.Sato 2024/03/21

                if( tr(ip,ie,it,icf(ix,iy,iz),im,3) .gt. 0.d0 ) then

                  call calc_stdev(m,Xa,sigx,
     &                            tr(ip,ie,it,icf(ix,iy,iz),im,3),
     &                            tr(ip,ie,it,icf(ix,iy,iz),im,4),
     &                            rtfac(m)/vl(ix,iy,iz)/ew(ie)/tw(it))

                  tr(ip,ie,it,icf(ix,iy,iz),im,3) = Xa
                  tr(ip,ie,it,icf(ix,iy,iz),im,4) = sigx

                else

                  isdz = 1
                  tr(ip,ie,it,icf(ix,iy,iz),im,3) = 0.d+0
                  tr(ip,ie,it,icf(ix,iy,iz),im,4) = 0.d+0

                end if

               endif ! end of history counter weighted

! sumover
              fact_in = rtfac(m)
              call pwwgxyz_sumover_stdev(0,m,ip,ie,it,ix,iy,iz,im,
     &             fact_in,ew(ie),tw(it),vl(ix,iy,iz),
     &             ew_sum,tw_sum,vl_x(iy,iz),vl_y(ix,iz),vl_z(ix,iy))

  101        continue

             if((ichnum(m).ne.0.or.ictnum(m).ne.0).and.im.eq.1) then ! T.Sato 2024/03/21, calculate min and max value for biased case

              if(ichplane(m).eq.1) then ! xy plane
               do iz = 1, nz

                trmax=0.0  ! T.Sato 2024/03/21 for biased mode
                fac=0.0    ! T.Sato 2024/03/21 for biased mode

                do iy = 1, ny
                 do ix = 1, nx
                  if( tr(ip,ie,it,icf(ix,iy,iz),im,3).gt.trmax ) then
                   trmax=tr(ip,ie,it,icf(ix,iy,iz),im,3)
                  endif
                 enddo
                enddo

                if(trmax.ne.0) then
                 if(ictnum(m).eq.0) then ! only chwei is defined
                  fac=(chbias(m)-1.0d0)/trmax
                 elseif(ichnum(m).eq.0) then ! only ctwei is defined
                  fac=(ctbias(m)-1.0d0)/trmax
                 else ! both chwei and ctwei are defined
                  fac=(max(ctbias(m),chbias(m))-1.0d0)/trmax
                 endif
                endif

                do iy = 1, ny
                 do ix = 1, nx
                  if( tr(ip,ie,it,icf(ix,iy,iz),im,1) .gt. 0.d0 ) then
                   tr(ip,ie,it,icf(ix,iy,iz),im,3)=
     &             tr(ip,ie,it,icf(ix,iy,iz),im,1) ! new factor
     &             /(1.0d0+fac*tr(ip,ie,it,icf(ix,iy,iz),im,3))
                   idimsize=idimsize+1
                   dimtmp(idimsize)=tr(ip,ie,it,icf(ix,iy,iz),im,3)
                  endif
                 enddo
                enddo

               enddo

              elseif(ichplane(m).eq.2) then ! yz plane

               do ix = 1, nx

                trmax=0.0  ! T.Sato 2024/03/21 for biased mode
                fac=0.0    ! T.Sato 2024/03/21 for biased mode

                do iz = 1, nz
                 do iy = 1, ny
                  if( tr(ip,ie,it,icf(ix,iy,iz),im,3).gt.trmax ) then
                   trmax=tr(ip,ie,it,icf(ix,iy,iz),im,3)
                  endif
                 enddo
                enddo

                if(trmax.ne.0) then
                 if(ictnum(m).eq.0) then ! only chwei is defined
                  fac=(chbias(m)-1.0d0)/trmax
                 elseif(ichnum(m).eq.0) then ! only ctwei is defined
                  fac=(ctbias(m)-1.0d0)/trmax
                 else ! both chwei and ctwei are defined
                  fac=(max(ctbias(m),chbias(m))-1.0d0)/trmax
                 endif
                endif

                do iz = 1, nz
                 do iy = 1, ny
                  if( tr(ip,ie,it,icf(ix,iy,iz),im,1) .gt. 0.d0 ) then
                   tr(ip,ie,it,icf(ix,iy,iz),im,3)=
     &             tr(ip,ie,it,icf(ix,iy,iz),im,1) ! new factor
     &             /(1.0d0+fac*tr(ip,ie,it,icf(ix,iy,iz),im,3))
                   idimsize=idimsize+1
                   dimtmp(idimsize)=tr(ip,ie,it,icf(ix,iy,iz),im,3)
                  endif
                 enddo
                enddo

               enddo

              elseif(ichplane(m).eq.3) then ! xz plane

               do iy = 1, ny

                trmax=0.0  ! T.Sato 2024/03/21 for biased mode
                fac=0.0    ! T.Sato 2024/03/21 for biased mode

                do iz = 1, nz
                 do ix = 1, nx
                  if( tr(ip,ie,it,icf(ix,iy,iz),im,3).gt.trmax ) then
                   trmax=tr(ip,ie,it,icf(ix,iy,iz),im,3)
                  endif
                 enddo
                enddo

                if(trmax.ne.0) then
                 if(ictnum(m).eq.0) then ! only chwei is defined
                  fac=(chbias(m)-1.0d0)/trmax
                 elseif(ichnum(m).eq.0) then ! only ctwei is defined
                  fac=(ctbias(m)-1.0d0)/trmax
                 else ! both chwei and ctwei are defined
                  fac=(max(ctbias(m),chbias(m))-1.0d0)/trmax
                 endif
                endif

                do iz = 1, nz
                 do ix = 1, nx
                  if( tr(ip,ie,it,icf(ix,iy,iz),im,1) .gt. 0.d0 ) then
                   tr(ip,ie,it,icf(ix,iy,iz),im,3)=
     &             tr(ip,ie,it,icf(ix,iy,iz),im,1) ! new factor
     &             /(1.0d0+fac*tr(ip,ie,it,icf(ix,iy,iz),im,3))
                   idimsize=idimsize+1
                   dimtmp(idimsize)=tr(ip,ie,it,icf(ix,iy,iz),im,3)
                  endif
                 enddo
                enddo

               enddo
              else ! all xyz plane

               trmax=0.0  ! T.Sato 2024/03/21 for biased mode
               fac=0.0    ! T.Sato 2024/03/21 for biased mode

               do iz = 1, nz
                do iy = 1, ny
                 do ix = 1, nx
                  if( tr(ip,ie,it,icf(ix,iy,iz),im,3).gt.trmax ) then
                   trmax=tr(ip,ie,it,icf(ix,iy,iz),im,3)
                  endif
                 enddo
                enddo
               enddo

               if(trmax.ne.0) then
                if(ictnum(m).eq.0) then ! only chwei is defined
                 fac=(chbias(m)-1.0d0)/trmax
                elseif(ichnum(m).eq.0) then ! only ctwei is defined
                 fac=(ctbias(m)-1.0d0)/trmax
                else ! both chwei and ctwei are defined
                 fac=(max(ctbias(m),chbias(m))-1.0d0)/trmax
                endif
               endif

               do iz = 1, nz
                do iy = 1, ny
                 do ix = 1, nx
                  if( tr(ip,ie,it,icf(ix,iy,iz),im,1) .gt. 0.d0 ) then
                   tr(ip,ie,it,icf(ix,iy,iz),im,3)=
     &             tr(ip,ie,it,icf(ix,iy,iz),im,1) ! new factor
     &             /(1.0d0+fac*tr(ip,ie,it,icf(ix,iy,iz),im,3))
                   idimsize=idimsize+1
                   dimtmp(idimsize)=tr(ip,ie,it,icf(ix,iy,iz),im,3)
                  endif
                 enddo
                enddo
               enddo
              endif

             endif

  110       continue ! end of im loop
            percentile=1.0d0-pedest(m)
            if(idimsize.ne.0) then ! data exist
             if(nt.eq.1) then
              call getemm(emm(ip,ie,1),emm(ip,ie,2),emm(ip,ie,3),
     &        percentile,idimsize,dimtmp(1))
             else
              call getemm(tmm(ip,it,1),tmm(ip,it,2),tmm(ip,it,3),
     &        percentile,idimsize,dimtmp(1))
             endif
            endif
  100       continue ! end of im loop


            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

         end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do 900 iax = 1, itfln(m)

         if( igsh .ne. 0 .and.
     &     ( itaxs(m,iax) .lt. 3 .or.
     &       ittwo(m) .eq. 4 .or. ittwo(m) .eq. 5 ) ) goto 900

         if( (itall .eq. 2 .and. nobch .lt. maxbch .and. igsh .eq. 0)
     &        .or. ( itall .eq. 4 .and. igsh .eq. 0 ) ) then

            call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &           nobch,maxbch,npe)

         else

              fname = ctfln(m,iax)

         end if

            iot = 31
            open(iot, file = fname, status = 'unknown' )

*-----------------------------------------------------------------------
            gfnam = ctfln(m,iax)
            igfmn = itfll(m,iax)
            igser = itger(m)

*-----------------------------------------------------------------------
*     input echo
*-----------------------------------------------------------------------

         if( itaxs(m,iax) .ne. 7 ) then

               call twwgech(iot,m,iax,1)

         end if

*-----------------------------------------------------------------------
*        wwg axis
*-----------------------------------------------------------------------

         if( itaxs(m,iax) .eq. 7 ) then

               im = 1

! T.Sato new normalization based on norm
         if(nt.eq.1) then
          if(normwwg(m).eq.1) then ! determine common normalization factor for energy and particle
           do ip=1,np
            tmpmax=0.0
            do i = 1, ne
             if(emm(ip,i,2).gt.tmpmax) tmpmax=emm(ip,i,2)
            enddo
            do i = 1, ne
             emm(ip,i,2)=tmpmax
            enddo
           enddo
          elseif(normwwg(m).eq.2) then ! determine common normalization factor for energy
           tmpmax=0.0
           do ip = 1,np
            do i = 1, ne
             if(emm(ip,i,2).gt.tmpmax) tmpmax=emm(ip,i,2)
            enddo
           enddo
           do ip = 1,np
            do i = 1, ne
             emm(ip,i,2)=tmpmax
            enddo
           enddo
          elseif(normwwg(m).eq.-1) then ! determine common normalization factor for energy and particle
           do ip=1,np
            tmpmin=1.0e30
            do i = 1, ne ! find minimum fluence
             if(emm(ip,i,3).ne.0.and.emm(ip,i,3).lt.tmpmin)
     &       tmpmin=emm(ip,i,3)
            enddo
            do i=1,ne
             if(emm(ip,i,3).ne.0) then
              emm(ip,i,2)=emm(ip,i,2)*tmpmin/emm(ip,i,3)
             endif
            enddo
           enddo
          elseif(normwwg(m).eq.-2) then ! determine common normalization factor for energy and particle
           tmpmin=1.0e30
           do ip=1,np
            do i = 1, ne ! find minimum fluence
             if(emm(ip,i,3).ne.0.and.emm(ip,i,3).lt.tmpmin)
     &       tmpmin=emm(ip,i,3)
            enddo
           enddo
           do ip=1,np
            do i=1,ne
             if(emm(ip,i,3).ne.0) then
              emm(ip,i,2)=emm(ip,i,2)*tmpmin/emm(ip,i,3)
             endif
            enddo
           enddo
          endif
         else
          if(normwwg(m).eq.1) then ! determine common normalization factor for energy and particle
           do ip=1,np
            tmpmax=0.0
            do i = 1, nt
             if(tmm(ip,i,2).gt.tmpmax) tmpmax=tmm(ip,i,2)
            enddo
            do i = 1, nt
             tmm(ip,i,2)=tmpmax
            enddo
           enddo
          elseif(normwwg(m).eq.2) then ! determine common normalization factor for energy
           tmpmax=0.0
           do ip = 1,np
            do i = 1, nt
             if(tmm(ip,i,2).gt.tmpmax) tmpmax=tmm(ip,i,2)
            enddo
           enddo
           do ip = 1,np
            do i = 1, nt
             tmm(ip,i,2)=tmpmax
            enddo
           enddo
          elseif(normwwg(m).eq.-1) then ! determine common normalization factor for energy and particle
           do ip=1,np
            tmpmin=1.0e30
            do i = 1, ne ! find minimum fluence
             if(tmm(ip,i,3).ne.0.and.tmm(ip,i,3).lt.tmpmin)
     &       tmpmin=tmm(ip,i,3)
            enddo
            do i=1,ne
             if(tmm(ip,i,3).ne.0) then
              tmm(ip,i,2)=tmm(ip,i,2)*tmpmin/tmm(ip,i,3)
             endif
            enddo
           enddo
          elseif(normwwg(m).eq.-2) then ! determine common normalization factor for energy and particle
           tmpmin=1.0e30
           do ip=1,np
            do i = 1, ne ! find minimum fluence
             if(tmm(ip,i,3).ne.0.and.tmm(ip,i,3).lt.tmpmin)
     &       tmpmin=tmm(ip,i,3)
            enddo
           enddo
           do ip=1,np
            do i=1,ne
             if(tmm(ip,i,3).ne.0) then
              tmm(ip,i,2)=tmm(ip,i,2)*tmpmin/tmm(ip,i,3)
             endif
            enddo
           enddo
          endif
         endif

         do ip = 1, np

               write(iot,'(/"[ Weight Window ]")')

                  write(iot,'("     mesh =  xyz",11x,
     &            " # mesh type is xyz scoring mesh")')

                  call echmty(0,iot,'x',itxty(m),itxnm(m),
     &                        rtxdl(m),rtxmi(m),rtxma(m),itxrg(m)
     &                        ,abs(itxnm(m)+1),das_itxrg)
                  call echmty(0,iot,'y',ityty(m),itynm(m),
