               write(iot,'("0.65 0")')
               write(iot,'("0.65 1.1")')
               write(iot,'("h: x y,l0")')
               write(iot,'("0.83 0")')
               write(iot,'("0.83 1.1")')
               write(iot,'("h: x y,l0")')
               write(iot,'("0.97 0")')
               write(iot,'("0.97 1.1")')

               write(iot,'("w: Statistical check sheet at batch"
