               write(iot,'("w: Current value / x(0.33) y(0.4) f(5)")')
               write(iot,'("w: ",0pf8.4," / x(0.65) y(0.4) f(5)")')
     &              deist(3,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
               write(iot,'("w: < 0.10 / x(0.84) y(0.4) f(5)")')
               if ( deist(3,
     &              initdeist+(ncurrbch-1)*sum(itism(1:itnm))+inum)
     &              .lt. 0.10d0 ) then
                  cpass = cyes
               else
                  cpass = cno
               end if
