               end if
               if(iloopmode .eq. 2) then
                  changelsub(4) = " "
               end if
               if(iloopmode .eq. 10) then
                  changelsub(5) = " "
               end if
               if(iloopmode .eq. 1) then
                  changelsub(6) = " "
               end if
                angeltitle = trim(changelsub(1))//trim(changelsub(2))//
     &                       trim(changelsub(3))//trim(changelsub(4))//
     &                       trim(changelsub(5))//trim(changelsub(6))//
     &                       trim(changelsub(7))
                write(iot,'(/a)') trim(angeltitle)

          end if

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdr: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdl: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn


               if( itmlp(m) .gt. 0 ) then
                     write(iot,'(
     &                     "  mset  &=& ",i3)')
     &                     itmnt(m,im)
               end if
               if(iloopmode .ge. 1) then
                     write(iot,'("  part  &=& ",a)') chp(ipi)(3:10)
               endif
               if( ittty(m) .ne. 0 ) then
                  write(iot,'(
     &                     "  tmin  &=&",1pe13.4," [nsec]"/
     &                     "  tmax  &=&",1pe13.4," [nsec]")')
     &                     tb(it), tb(it+ntstepi)
               end if
                     write(iot,'("e:")')

            end do

            end do
            end do
            end do

*-----------------------------------------------------------------------
*        time axis
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 2 ) then

               inum = 0

            nmstepi = 1
            do iri = 1, nr, nrstepi
            do imi = 1, nm
            do iei = 1, ne, nestepi
            do ipi = 1, np, npstepi
               ir = iri
               im = imi
               ie = iei
               ip = ipi

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               if(iloopmode .ge. 1) then
                  write(iot,'("#   ",a)') chp(ipi)(3:10)
               endif

               if( itpon(m) .eq. 1 ) then
                  write(iot,'("#   no. =",i3,3x,"point# =",i3)')
     &                        inum, ir
                  write(iot,'("#     x =",1p1g13.4,"  y =",1p1g13.4,
     &                            "  z =",1p1g13.4 )')
     &                       rtpon(m,ir,1),rtpon(m,ir,2),rtpon(m,ir,3)
               else
                  write(iot,'("#   no. =",i3,3x,"ring# =",i3)')
     &                        inum, ir
                  if( nint(rtpon(m,ir,1)) .eq. 1 ) then
                     write(iot,'("# axis = x   ar =",1p1g13.4,
     &                            "  rr =",1p1g13.4 )')
     &                             rtpon(m,ir,2),rtpon(m,ir,3)
                  else if( nint(rtpon(m,ir,1)) .eq. 2 ) then
                     write(iot,'("# axis = y   ar =",1p1g13.4,
     &                            "  rr =",1p1g13.4 )')
     &                             rtpon(m,ir,2),rtpon(m,ir,3)
                  else if( nint(rtpon(m,ir,1)) .eq. 3 ) then
                     write(iot,'("# axis = z   ar =",1p1g13.4,
     &                            "  rr =",1p1g13.4 )')
     &                             rtpon(m,ir,2),rtpon(m,ir,3)
                  end if
               end if


               if( itmlp(m) .gt. 0 )
     &            write(iot,'("#   mset =",i3)') itmnt(m,im)
                  write(iot,'(
     &            "#  ie =",i3,/
     &            "#   e = (",1p1e13.4,"  -",1p1e13.4,"  )")')
     &                     ie, eb(ie), eb(ie+nestepi)

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'(/"x: Time [nsec]")')

               else

                  write(iot,'(/"x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: Flux ",a29)') hsunit(itunt(m))

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               if( ittty(m) .eq. 3 .or. ittty(m) .eq. 5 ) then

                  write(iot,'( "p: xlog ylog afac(0.8) form(0.9)")')

               else

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

               end if

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &            ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

       include 'samepage_include/petrm_time.inc'
*-----------------------------------------------------------------------

          if(iloopmode .eq. 0) then
            if( itpon(m) .eq. 1 ) then
               if( itmlp(m) .eq. 0 ) then
                     write(iot,'(/a1,"no. =",i3,
     &                        ",  point# =",i3,",  ie =",i3,a1)')
     &                        cha, inum, ir, ie, cha
               else
                     write(iot,'(/a1,"no. =",i3,
     &                        ",  point# =",i3,
     &                        ",  mset =",i3,",  ie =",i3,a1)')
     &                        cha, inum, ir, itmnt(m,im), ie, cha
               end if
            else
               if( itmlp(m) .eq. 0 ) then
                     write(iot,'(/a1,"no. =",i3,
     &                        ",  ringt# =",i3,",  ie =",i3,a1)')
     &                        cha, inum, ir, ie, cha
               else
                     write(iot,'(/a1,"no. =",i3,
     &                        ",  ring# =",i3,
     &                        ",  mset =",i3,",  ie =",i3,a1)')
     &                        cha, inum, ir, itmnt(m,im), ie, cha
               end if
            end if

          else
                write(changelsub(1),'(a1,"no. =",i3)') cha,inum
                write(changelsub(2),'(",  part = ",a)') chp(ipi)(3:10)
                if( itmlp(m) .eq. 0 ) then
                  changelsub(3) = " "
                else
                  write(changelsub(3),'(",  mset =",i3)') itmnt(m,im)
                end if
                if( itpon(m) .eq. 1 ) then
                  write(changelsub(4),'(",  point# =",i3)') ir
                else
                  write(changelsub(4),'(",  ring# =",i3)') ir
                end if
                write(changelsub(5),'(",  it =",i3)') it
                write(changelsub(6),'(",  ie =",i3)') ie
                write(changelsub(7),'(a1)') cha

               changelsub(5) = " "
               if( itmlp(m) .eq. 0 ) then
                  changelsub(3) = " "
               end if
               if( ittty(m) .eq. 0 ) then
                  changelsub(5) = " "
               end if
               if(iloopmode .eq. 2) then
                  changelsub(4) = " "
               end if
               if(iloopmode .eq. 10) then
                  changelsub(5) = " "
               end if
               if(iloopmode .eq. 1) then
                  changelsub(6) = " "
               end if
                angeltitle = trim(changelsub(1))//trim(changelsub(2))//
     &                       trim(changelsub(3))//trim(changelsub(4))//
     &                       trim(changelsub(5))//trim(changelsub(6))//
     &                       trim(changelsub(7))
                write(iot,'(/a)') trim(angeltitle)

          end if

               write(iot,'("msuc: {",a1,"huge ",80a1)')
     &                  yen, ( ittle(m)(i:i), i = 1, ittll(m) ), rpa

               write(iot,'("msdr: {",a1,"it plotted by ",
     &                  a1,"ANGEL ",a1,"version}")') yen, yen, yen
               write(iot,'("msdl: {",a1,"it calculated by ",
     &                  a1,"PHITS ",f5.2"}")') yen, yen, versn


               if( itmlp(m) .gt. 0 ) then
                     write(iot,'(
     &                     "  mset  &=& ",i3)')
     &                     itmnt(m,im)
               end if

               if(iloopmode .ge. 1) then
                     write(iot,'("  part  &=& ",a)') chp(ipi)(3:10)
               endif
                  if( iMeVperu.eq.0 ) then
                     write(iot,'(
     &                     "  emin  &=&",1pe13.4," [MeV]"/
     &                     "  emax  &=&",1pe13.4," [MeV]")')
     &                     eb(ie), eb(ie+nestepi)
                  else
                     write(iot,'(
     &                     "  emin  &=&",1pe13.4," [MeV/n]"/
     &                     "  emax  &=&",1pe13.4," [MeV/n]")')
     &                     eb(ie), eb(ie+nestepi)
                  end if
                     write(iot,'("e:")')

            end do

            end do
            end do
            end do


*-----------------------------------------------------------------------

         end if


            call prestart(m,iot) !OBINATA(2012.6.13)

            close(iot)

         if( iteps(m) .ne. 0 ) then

            open(iot, file = fname, status = 'unknown' )
            call a_angel(idasa,fname)

         end if

*-----------------------------------------------------------------------

  900 continue

*-----------------------------------------------------------------------
      include 'samepage_include/samepage999.inc'


      return
      end


************************************************************************
*                                                                      *
      subroutine tsedreg(ncol,m,nl,lt,np,nr,mr,ne,kr,eb,tr,trEVENT)
*                                                                      *
*       SED tally in region mesh                                       *
*       last modified by T.Sato on 2009/02/27                          *
*       written by T.Sato on 2005/10/20                                *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt ! frtati 2021/10/05
      use TSEDMOD  ! T.Sato 2022/08/15
*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      include 'zdist.inc'

      include 'err.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)
      common /tlglat/ ilev1,ilev2,ilat1(5,10),ilat2(5,10)
!$OMP THREADPRIVATE(/tlglat/)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall50/ itlmt(itlmax), ite2l(itlmax)   ! CCSE 2022.08.31
      common /tall51/ eletb(2000), nlete
      common /tall57/ itsun(itlmax),rtdim(itlmax),rtucv(itlmax),
     &rtrho(itlmax),itmodel(itlmax) ! T.Sato 2022/08/14

      common /tall82/ itcnth(9,itlmax)

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   tr(np,ne,nr,2)
      dimension   trEVENT(np,ne,nr)         !OBINATA(2012.9.7): as Ct
      real(8),allocatable,save:: tr0(:,:,:) !OBINATA(2012.9.7): as C

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt
      dimension facm(6)

      dimension   ratio(ne+1),rati2(ne+1)
      data izpoor / 0 /
      save izpoor !FURUTA
!$OMP THREADPRIVATE(izpoor)

*-----------------------------------------------------------------------

      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas

*-----------------------------------------------------------------------
      common /dedxfac/ dedxfd
!$OMP THREADPRIVATE(/dedxfac/)

*-----------------------------------------------------------------------

      integer iegsemi, iegsout
      common /egsemi/ iegsemi, iegsout

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
 !                trEVENT = 0.d0
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.9.5): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
 !          if ( nocas .gt. 1 .or. ncol .eq. 0 ) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             tr(:,:,:,1) = tr(:,:,:,1) + trEVENT(:,:,:)
             tr(:,:,:,2) = tr(:,:,:,2) + trEVENT(:,:,:) ** 2

! sumoveer
             call tsedreg_sumover(m,1,
     &                   np,  ne, nr, trEVENT)

           end if

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.9.5): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nr) )
             tr0(:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (tsedreg_crit_ist1)
             tr0(:,:,:) = tr0(:,:,:) + trEVENT(:,:,:)
!$OMP END CRITICAL (tsedreg_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,1) = tr(:,:,:,1) + tr0(:,:,:) / maxcas
             tr(:,:,:,2) = tr(:,:,:,2)
     &                     + ( tr0(:,:,:) / maxcas ) ** 2

      call tsedreg_sumover(m,maxcas,
     &                   np,  ne, nr, tr0)

             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        check region
*-----------------------------------------------------------------------

               jj = 0

            do ii = 1, nr

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .ne. 0 ) goto 501

           end do

               return

  501      continue

*-----------------------------------------------------------------------
*        material for LET
*-----------------------------------------------------------------------

               if( itlmt(m) .gt. 0 ) then

                  lmat = idnm( itlmt(m) )

               else if( itlmt(m) .eq. 0 ) then

                  lmat = mat

               else

                  lmat = -idnm( -itlmt(m) )

               end if

*-----------------------------------------------------------------------
*           track length
*-----------------------------------------------------------------------

               tlngth = sqrt( ( xc(ibkxc+no,ipomp+1) -
     &                                         x(ibkx+no,ipomp+1) )**2
     &                      + ( yc(ibkyc+no,ipomp+1) -
     &                                         y(ibky+no,ipomp+1) )**2
     &                      + ( zc(ibkzc+no,ipomp+1) -
     &                                         z(ibkz+no,ipomp+1) )**2 )

*-----------------------------------------------------------------------
*           initial and final energy
*-----------------------------------------------------------------------

                  ein = e(ibke+no,ipomp+1)
                  ecc = ec(ibkec+no,ipomp+1)
                  ecc = ein - dedxfd * ( ein - ecc )

                  if( ncol .eq. 9 .or. ncol .eq. 11 ) ecc = 0.d0

*-----------------------------------------------------------------------
cKN Iwase 2014/08/22 for EGS

               if( ( ityp.eq.12 .or. ityp.eq.13 .or. ityp.eq.14 ) .and.
     &               iegsemi .ne. 0 ) then

                     call egs5edxde(ecc,tlngth,ein,mat,ityp)

               endif

*-----------------------------------------------------------------------

               do i = 1, nlete

                  if( ein .ge. eletb(i) .and.
     &                ein .lt. eletb(i+1) ) goto 30

               end do

   30             ie1 = min( i, nlete )

               do i = nlete, 1, -1

                  if( ecc .ge. eletb(i) .and.
     &                ecc .lt. eletb(i+1) ) goto 40

               end do

   40             ie2 = max( i, 1 )

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

               rrl = tlngth
               rrr = tlngth
               rrt = 0.0d0

            if( mat .gt. 0 .and. jtyp .ne. 0 ) then

                  call rainge(ein,rng0,mat,ityp,ktyp,jtyp,rtyp)

                  rng1 = max( 0.0d0, rng0 - tlngth )

                  if( rng1 .gt. 1.d+30 ) return

               if( ein .gt. eletb(nlete+1) ) then

                  call rainge(eletb(nlete+1),rngm,mat,
     &                        ityp,ktyp,jtyp,rtyp)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

               end if

            end if

               rrl0 = rrl
               rrr0 = rrr
               rrt0 = rrt

*-----------------------------------------------------------------------
*     check of region
*-----------------------------------------------------------------------

                  jj = 0

*-----------------------------------------------------------------------

      do 100 ii = 1, nr

*-----------------------------------------------------------------------

               call tregck(iblz1,ilev1,ilat1,mr,kr,jj,icc)

               if( icc .eq. 0 ) goto 100

               ir = ii

*-----------------------------------------------------------------------
*        check of particles, only charged particles
*-----------------------------------------------------------------------

               if( jtyp .eq. 0 ) goto 200

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 )  goto 200

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                   goto 200

               end if

            end do

*-----------------------------------------------------------------------
*        check of energy
*-----------------------------------------------------------------------

               if( ein .lt. eletb(1) ) goto 200
               if( ecc .ge. eletb(nlete+1) ) goto 200

*-----------------------------------------------------------------------

               rrl = rrl0
               rrr = rrr0
               rrt = rrt0

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 270 ie = ie1, ie2, -1

                     emie = max( ecc, eletb(ie) )
                     emiu = min( ein, eletb(ie+1) )
                  if( emiu * emie .gt. 0.d0 ) then
                     erg  = sqrt( emiu * emie )
                  else
                     erg  = emiu / 2.d0
                  end if
                     eff  = emiu - emie

                  if( mat .gt. 0 ) then

                     call rainge(emie,rng,mat,ityp,ktyp,jtyp,rtyp)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                        ecc .gt. eletb(ie) ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

                  end if

*-----------------------------------------------------------------------
*              LET bin
*-----------------------------------------------------------------------

               call dedxas(erg,dedx,lmat,ityp,ktyp,jtyp,rtyp)

                  dedx = dedx / 10.d0

                  if( itunt(m) .eq. 1 .or. itunt(m) .eq. 3 .or.
     &                itunt(m) .eq. 5 ) then

                        tlv0 = oldwt * rrl

                  else

                        tlv0 = oldwt * eff

               if( ( ityp.eq.12 .or. ityp.eq.13 .or. ityp.eq.14 ) .and.
     &         (ncol.eq.9.or.ncol.eq.11).and.ie.eq.ie2)
     &         tlv0 = tlv0 + oldwt*erg  ! T.Sato 2022/08/17, add cut-off energy

                  end if

*-----------------------------------------------------------------------

                 if(dedx .le. 1.0e-6) goto 264

                     CelDiam   = abs(rtdim(m))  ! T.Sato 2021/10/07
                     unitconv  = rtucv(m)

                  if( ityp .eq. 12 .or. ityp .eq. 13 .or.
     &                ityp .eq.  6 .or. ityp .eq.  7 ) then

                   if(itmodel(m).ge.1) then
                    if((ncol.eq.9.or.ncol.eq.11).and.ie.eq.ie2) then ! stopped electron
                     call getAparastp(rtdim(m)*rtrho(m),erg,itmodel(m))
                    else
                     call getAparaele(rtdim(m)*rtrho(m),erg,itmodel(m))
                    endif
                    depev=0.0 ! not used for electron mode
                   else
                     call getfitele(CelDiam*rtrho(m),erg)
                   endif

                  else

                     izz = abs(jtyp)
                     if( izz .gt. 26 ) izz = 26

                     AA = 1.0
                     if( ityp .ge. 15 )
     &               AA = dble( ktyp - ktyp / 1000000 * 1000000 )

                 if(itmodel(m).ge.1) then
                   depev=min(dedx*CelDiam*1.0e3,erg*1.0d6)  ! max deposition energy in eV
                   call getAparaion(CelDiam*rtrho(m),erg/AA,izz,
     &             depev,itmodel(m))
                 else
                   call getfit(CelDiam*rtrho(m),izz,erg/AA,dedx*10.0)
                 endif

                  end if

                  do i = 1, ne + 1
                     ratio(i) = 0.0
                     rati2(i) = 0.0
                  end do

        if(itmodel(m).ge.1) then ! new model 2022/08/16

         tmp=sedmean(1.0d0,depev) ! get Apara(9)
         if(itsun(m).eq.0) then ! number of event
          factor=1.0d0
         else  ! convert MeV to number of event
          factor=1.0e6/Apara(9)
         endif

         do i = 1, ne

          zlow = factor*unitconv *   eb(i)   ! number of event
          zhig = factor*unitconv *   eb(i+1)
          zwid = factor*unitconv * ( eb(i+1) - eb(i) )
          zmid = factor*unitconv * ( eb(i+1) + eb(i) ) / 2.d0

          zdfzmzw = zmid*sedmean(zmid,depev) * zwid  ! zf(z)dz
          ratio(i) = zdfzmzw
          rati2(i) = zdfzmzw/zmid

          ratio(ne+1) = ratio(ne+1) + ratio(i)
          rati2(ne+1) = rati2(ne+1) + rati2(i)

         enddo

        else ! old model

                  do i = 1, ne

                     zlow = unitconv *   eb(i)
                     zhig = unitconv *   eb(i+1)
                     zwid = unitconv * ( eb(i+1) - eb(i) )
                     zmid = unitconv * ( eb(i+1) + eb(i) ) / 2.d0

                     tmpcomp=Ccurr(1)*100.0
                     if(tmpcomp .le. 5.0e-3) tmpcomp=5.0e-3
                     if( zmid .gt. tmpcomp ) goto 777

                     if( zhig .lt. Pmid(iponly) ) then

                        ratio(i) = Pcurr(1) / Pmid(iponly) * zwid
                        rati2(i) = Pcurr(1) / Pmid(iponly) * zwid/zmid

                     else

                        if(rtdim(m).ge.0) then  ! T.Sato 2021/10/07, consider Auger contribution

                          do ip = iponly, npeak-1

                           if(zlow .le. Pmid(ip) .and.
     &                        zhig .gt. Pmid(ip) ) then

                              ratio(i) = ratio(i) + Pcurr(ip)
                              rati2(i)=  rati2(i)+ Pcurr(ip) / zmid

                           end if

                          end do

                          if(zlow .le. Pmid(npeak) .and.
     &                     zhig .gt. Pmid(npeak) ) then

                           z0 = Pmid(npeak)

                           Auger(0)=(Gau(zlow-z0,Wauger)+1)*abs(zlow-z0)
     &                             +(Gau(zhig-z0,Wauger)+1)*abs(zhig-z0)

                           Atotal=Auger(0)

                           do k = -1,-maxAuger+1,-1

                              zl = unitconv *   eb(i+k)
                              zh = unitconv *   eb(i+k+1)

                              Auger(k)=(Gau(zl-z0,Wauger)
     &                        +Gau(zh-z0,Wauger))*(zh-zl)

                              Atotal = Atotal + Auger(k)

                              if(Auger(k).le.Auger(0)*1.0e-2) goto 333
                              if(i+k.eq.1) goto 333

                           end do

 333                       ilow = k

                           do k = 1, maxAuger-1

                              zl = unitconv *   eb(i+k)
                              zh = unitconv *   eb(i+k+1)

                              Auger(k)=(Gau(zl-z0,Wauger)
     &                        +Gau(zh-z0,Wauger))*(zh-zl)

                              Atotal = Atotal + Auger(k)

                              if(Auger(k).le.Auger(0)*1.0e-2) goto 444
                              if(i+k.ge.ne-1) goto 444

                           end do

 444                       ihig = k

                           do k = ilow, ihig

                              zmm = unitconv*(eb(i+k)+eb(i+k+1))*0.5

                              ratio(i+k) = ratio(i+k) + Pcurr(npeak)
     &                        * Auger(k)/Atotal
                              rati2(i+k) = rati2(i+k) + Pcurr(npeak)
     &                        * Auger(k)/Atotal / zmm

                           end do

                         end if

                      else ! for negative cdiam, ignore Auger peak

                        do ip = iponly, npeak-2

                         if(zlow .le. Pmid(ip) .and.
     &                      zhig .gt. Pmid(ip) ) then

                            ratio(i) = ratio(i) + Pcurr(ip)
                            rati2(i)=  rati2(i)+ Pcurr(ip) / zmid

                         end if

                        end do

                      endif

                      zdfzmzw = zdistfunc(zmid) * zwid
                      ratio(i) = ratio(i) + zdfzmzw
                      rati2(i) = rati2(i) + zdfzmzw/zmid

                     end if

                     ratio(ne+1) = ratio(ne+1) + ratio(i)
                     rati2(ne+1) = rati2(ne+1) + rati2(i)

                  end do

  777             if( ratio(ne+1) .lt. 0.5) then

                     write(ErrCha,*) 'Warning: Z bin is not enough !'
                     ErrID = 'L:20445/R:tsedreg/F:talls07.f' !W61_001_001
                     call ErrWrite(ErrID,ErrCha)
                     if( ratio(ne+1) .eq. 0.0) ratio(ne+1)=1.0

                     izpoor = izpoor + 1
                     if( izpoor .gt. 1000 ) then
                      write(ErrCha,*) 'Too poor of Z bin !!!'
                      ErrID = 'L:20452/R:tsedreg/F:talls07.f' !E61_002_001
                      call ErrWrite(ErrID,ErrCha)
                      call parastop( 666 )
                     end if

                  end if

         endif  ! end of old model

                  do i = 1, ne

                     if( itunt(m) .eq. 1 .or. itunt(m) .eq. 3 .or.
     &                   itunt(m) .eq. 5 ) then

! nais
                         if(rati2(ne+1) .ne. 0.0d0) then
                           tlv = tlv0 * rati2(i) / rati2(ne+1)
                         else
                           tlv = 0.0d0
                         endif

                     else

! nais
                         if(ratio(ne+1) .ne. 0.0d0) then
                           tlv = tlv0 * ratio(i) / ratio(ne+1)
                         else
                           tlv = 0.0d0
                         endif

                     end if

                     if ( .not. tlv .gt. 0.d0 ) tlv = 0.d0
                     do ip = 1, ipn
cOBINATA(2012.9.7): Ct = Ct + xi.wi
                        trEVENT(ips(ip),i,ir) =
     &                  trEVENT(ips(ip),i,ir) + tlv

                     end do
                  end do

*-----------------------------------------------------------------------

  264             rrr = rrr - rrl

  270       continue

*-----------------------------------------------------------------------

  200       continue

*-----------------------------------------------------------------------
*     dead particles of produced charged particle
*-----------------------------------------------------------------------

      if( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &      mat .gt. 0 .and. nclsts .gt. 0 ) then

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( jcount(i,1) .lt. itcnt(i*2+2,m) .or.
     &                jcount(i,1) .gt. itcnt(i*2+3,m) ) goto 300

               end if

            end do

*-----------------------------------------------------------------------
*        dead particle and nucleus
*-----------------------------------------------------------------------

         do j = 1, nclsts

         if( jclusts(4,j) .lt. 0 .and. jclusts(5,j) .ne. 0 .and.
     &       qclusts(7,j) .gt. eletb(1) ) then


                  ipart = jclusts(3,j)
                  kpart = jclusts(7,j)
                  jpart = jclusts(5,j)
                  rpart = qclusts(5,j) * 1000.d0

*-----------------------------------------------------------------------

            call pcheck(m,np,ipart,kpart,jpart,ipn,ips)

               if( ipn .eq. 0 )  goto 285

           if( itunt(m) .eq. 1 .or. itunt(m) .eq. 3 .or.
     &         itunt(m) .eq. 5 ) goto 285  ! T.Sato 2022/08/19, not necessary to consider dead particle for track length mode

*-----------------------------------------------------------------------

                  ein = qclusts(7,j)
                  ecc = 0.0d0

               if( ein .lt. eletb(1) ) goto 285

*-----------------------------------------------------------------------

             if(ipart.ge.12.and.ipart.le.14) then ! for electron, positron, photon, T.Sato 2022/08/19
               ie1=1
               ie2=1
               tlv0=ein*qclusts(8,j)
               erg=tlv0
             else

               do i = 1, nlete

                  if( ein .ge. eletb(i) .and.
     &                ein .lt. eletb(i+1) ) goto 35

               end do

   35             ie1 = min( i, nlete )
                  ie2 = 1

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

                  call rainge(ein,rng0,mat,
     &                        ipart,kpart,jpart,rpart)

! T.Sato 2015/2/27, electron and positrons are OK when rng0 > 1.d30
                  if( abs(kpart).ne.11.and.rng0.gt.1.d+30) goto 285

                  tlngth = rng0
                  rng1 = 0.0d0

                  rrl = tlngth
                  rrr = tlngth
                  rrt = 0.0d0

               if( ein .gt. eletb(nlete+1) ) then

                  call rainge(eletb(nlete+1),rngm,mat,
     &                        ipart,kpart,jpart,rpart)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

               end if
            endif
*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 275 ie = ie1, ie2, -1

             if(ipart.ge.12.and.ipart.le.14) goto 276  ! T.Sato 2022/08/19

                     emie = max( ecc, eletb(ie) )
                     emiu = min( ein, eletb(ie+1) )
                  if( emiu * emie .gt. 0.d0 ) then
                     erg  = sqrt( emiu * emie )
                  else
                     erg  = emiu / 2.d0
                  end if
                     eff  = emiu - emie

                  if( mat .gt. 0 ) then

                     call rainge(emie,rng,mat,
     &                           ipart,kpart,jpart,rpart)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                        ecc .gt. eletb(ie) ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

                  end if

*-----------------------------------------------------------------------
*              LET bin
*-----------------------------------------------------------------------

               call dedxas(erg,dedx,lmat,ipart,kpart,jpart,rpart)

               dedx = dedx / 10.d0

               tlv0 = qclusts(8,j) * eff

*-----------------------------------------------------------------------

                 if(dedx .le. 1.0e-6) goto 265

 276              CelDiam   = abs(rtdim(m))  ! T.Sato 2021/10/07
                  unitconv  = rtucv(m)

cTS2012/5/11 jtyp->jpart, ityp->ipart, ktyp->kpart

                  if( ipart .eq. 12 .or. ipart .eq. 13 .or.
     &                ipart .eq.  6 .or. ipart .eq.  7 ) then

                   if(itmodel(m).ge.1) then
                    call getAparastp(rtdim(m)*rtrho(m),erg,itmodel(m))
                    depev=0.0 ! not used for electron mode
                   else
                    call getfitele(CelDiam*rtrho(m),erg)
                   endif

                  else

                     izz = abs(jpart)
                     if( izz .gt. 26 ) izz = 26

                     AA = 1.0
                     if( ipart .ge. 15 )
     &               AA = dble( kpart - kpart / 1000000 * 1000000 )

                 if(itmodel(m).ge.1) then
                   depev=min(dedx*CelDiam*1.0e3,erg*1.0d6)  ! max deposition energy in eV
                   call getAparaion(CelDiam*rtrho(m),erg/AA,izz,
     &             depev,itmodel(m))
                 else
                   call getfit(CelDiam*rtrho(m),izz,erg/AA,dedx*10.0)
                 endif

                  end if

                     do i = 1, ne + 1
                        ratio(i) = 0.0
                        rati2(i) = 0.0
                     end do

        if(itmodel(m).ge.1) then ! new model 2022/08/16

         tmp=sedmean(1.0d0,depev) ! get Apara(9)
         if(itsun(m).eq.0) then ! number of event
          factor=1.0d0
         else  ! convert MeV to number of event
          factor=1.0e6/Apara(9)
         endif

         do i = 1, ne

          zlow = factor*unitconv *   eb(i)   ! number of event
          zhig = factor*unitconv *   eb(i+1)
          zwid = factor*unitconv * ( eb(i+1) - eb(i) )
          zmid = factor*unitconv * ( eb(i+1) + eb(i) ) / 2.d0

          zdfzmzw = zmid*sedmean(zmid,depev) * zwid  ! zf(z)dz
          ratio(i) = zdfzmzw
          rati2(i) = zdfzmzw/zmid

          ratio(ne+1) = ratio(ne+1) + ratio(i)
          rati2(ne+1) = rati2(ne+1) + rati2(i)

         enddo

        else ! old model

                  do i = 1, ne

                     zlow = unitconv *   eb(i)
                     zhig = unitconv *   eb(i+1)
                     zwid = unitconv * ( eb(i+1) - eb(i) )
                     zmid = unitconv * ( eb(i+1) + eb(i) ) / 2.d0

                     tmpcomp=Ccurr(1)*100.0
                     if(tmpcomp .le. 5.0e-3) tmpcomp=5.0e-3
                     if( zmid .gt. tmpcomp ) goto 888

                     if( zhig .lt. Pmid(iponly) ) then

                        ratio(i) = Pcurr(1) / Pmid(iponly) * zwid
                        rati2(i) = Pcurr(1) / Pmid(iponly) * zwid/zmid

                     else

                      if(rtdim(m).ge.0) then  ! T.Sato 2021/10/07, consider Auger contribution


                        do ip = iponly, npeak-1

                           if(zlow .le. Pmid(ip) .and.
     &                        zhig .gt. Pmid(ip) ) then

                              ratio(i) = ratio(i) + Pcurr(ip)
                              rati2(i)=  rati2(i)+ Pcurr(ip) / zmid

                           end if

                        end do

                        if(zlow .le. Pmid(npeak) .and.
     &                     zhig .gt. Pmid(npeak) ) then

                           z0 = Pmid(npeak)

                           Auger(0)=(Gau(zlow-z0,Wauger)+1)*abs(zlow-z0)
     &                             +(Gau(zhig-z0,Wauger)+1)*abs(zhig-z0)

                           Atotal=Auger(0)

                           do k = -1,-maxAuger+1,-1

                              zl = unitconv *   eb(i+k)
                              zh = unitconv *   eb(i+k+1)

                              Auger(k)=(Gau(zl-z0,Wauger)
     &                        +Gau(zh-z0,Wauger))*(zh-zl)

                              Atotal = Atotal + Auger(k)

                              if(Auger(k).le.Auger(0)*1.0e-2) goto 334
                              if(i+k.eq.1) goto 334

                           end do

 334                       ilow = k

                           do k = 1, maxAuger-1

                              zl = unitconv *   eb(i+k)
                              zh = unitconv *   eb(i+k+1)

                              Auger(k)=(Gau(zl-z0,Wauger)
     &                        +Gau(zh-z0,Wauger))*(zh-zl)

                              Atotal = Atotal + Auger(k)

                              if(Auger(k).le.Auger(0)*1.0e-2) goto 445
                              if(i+k.ge.ne-1) goto 445

                           end do

 445                       ihig = k

                           do k = ilow, ihig

                              zmm = unitconv*(eb(i+k)+eb(i+k+1))*0.5

                              ratio(i+k) = ratio(i+k) + Pcurr(npeak)
     &                        * Auger(k)/Atotal
                              rati2(i+k) = rati2(i+k) + Pcurr(npeak)
     &                        * Auger(k)/Atotal / zmm

                           end do

                        end if

                        zdfzmzw = zdistfunc(zmid) * zwid
                        ratio(i) = ratio(i) + zdfzmzw
                        rati2(i) = rati2(i) + zdfzmzw/zmid

                      else  ! except for Auger

                        do ip = iponly, npeak-2

                           if(zlow .le. Pmid(ip) .and.
     &                        zhig .gt. Pmid(ip) ) then

                              ratio(i) = ratio(i) + Pcurr(ip)
                              rati2(i)=  rati2(i)+ Pcurr(ip) / zmid

                           end if

                        end do

                      endif

                     end if

                     ratio(ne+1) = ratio(ne+1) + ratio(i)
                     rati2(ne+1) = rati2(ne+1) + rati2(i)

                  end do

  888             if( ratio(ne+1) .lt. 0.5) then

                     write(ErrCha,*) 'Warning: Z bin is not enough !'
                     ErrID = 'L:20843/R:tsedreg/F:talls07.f' !W61_001_002
                     call ErrWrite(ErrID,ErrCha)

                     if( ratio(ne+1) .eq. 0.0) ratio(ne+1)=1.0

                     izpoor = izpoor + 1
                     if( izpoor .gt. 1000 ) then
                       write(ErrCha,*) 'Too poor of Z bin !!!'
                       ErrID = 'L:20851/R:tsedreg/F:talls07.f' !E61_002_002
                       call ErrWrite(ErrID,ErrCha)
                       call parastop( 666 )
                     end if

                  end if

             endif ! end of old model

                  do i = 1, ne

! nais
                     if(ratio(ne+1) .ne. 0.0d0) then
                       tlv = tlv0 * ratio(i) / ratio(ne+1)
                     else
                       tlv = 0.0d0
                     endif

                     if ( .not. tlv .gt. 0.d0 ) tlv = 0.d0
                     do ip = 1, ipn
cOBINATA(2012.9.7): Ct = Ct + xi.wi
                        trEVENT(ips(ip),i,ir) =
     &                  trEVENT(ips(ip),i,ir) + tlv

                     end do

                  end do

*-----------------------------------------------------------------------

  265       continue

            if(ipart.lt.12.or.ipart.gt.14)  rrr = rrr - rrl

  275       continue

*-----------------------------------------------------------------------

  285       continue

         end if
         end do

*-----------------------------------------------------------------------

  300    continue

      end if

*-----------------------------------------------------------------------

  100 continue

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine psedreg(m,np,nr,mr,ne,kr,eb,tr,
     &                   nvl,ivl,rvl,
     &                   nx,ny,nz,xm,ym,zm,igsh,idasa)
*                                                                      *
*       output the SED tally in region mesh                            *
*       last modified by K.Niita on 2006/02/09                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall21/ rtfac(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall49/ itglt(itlmax)

      common /tall57/ itsun(itlmax),rtdim(itlmax),rtucv(itlmax),
     &rtrho(itlmax),itmodel(itlmax) ! T.Sato 2022/08/14

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31

*-----------------------------------------------------------------------

      common /volreg/ dvol(kvlmax)

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   kr(mr)
      dimension   eb(ne+1)
      dimension   ew(ne)
      dimension   vl(nr)
      dimension   lr(nr)
      dimension   tr(np,ne,nr,2)
      dimension   ivl(nvl)
      dimension   rvl(nvl)

      dimension   xm(nx+1)
      dimension   ym(ny+1)
      dimension   zm(nz+1)
      dimension   val(nr)

      integer,allocatable :: ixyz(:)

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> np
      dimension tott(np,2),totnorm(np) ! totnorm is added on 2017/11/21 for normalization

      character hsunit(32)*30

      data hsunit(1) / 'T.L. [cm/event/source]'/
      data hsunit(2) / 'T.L. [cm/MeV/source]'/
      data hsunit(3) / 'T.L. [cm/(keV/um)/source]'/
      data hsunit(4) / 'T.L. [cm/Gy/source]'/
      data hsunit(5) / 'Dose [MeV/event/source]'/
      data hsunit(6) / 'Dose [MeV/MeV/source]'/
      data hsunit(7) / 'Dose [MeV/(keV/um)/source]'/
      data hsunit(8) / 'Dose [MeV/Gy/source]'/
      data hsunit(9) / 'T.L. [cm/ln(event)/source]'/
      data hsunit(10)/ 'T.L. [cm/ln(MeV)/source]'/
      data hsunit(11)/ 'T.L. [cm/ln(keV/um)/source]'/
      data hsunit(12)/ 'T.L. [cm/ln(Gy)/source]'/
      data hsunit(13)/ 'Dose [MeV/ln(event)/source]'/
      data hsunit(14)/ 'Dose [MeV/ln(MeV)/source]'/
      data hsunit(15)/ 'Dose [MeV/ln(keV/um)/source]'/
      data hsunit(16)/ 'Dose [MeV/ln(Gy)/source]'/
      data hsunit(17)/ 'T.L. [cm/source]'/
      data hsunit(18)/ 'T.L. [cm/source]'/
      data hsunit(19)/ 'T.L. [cm/source]'/
      data hsunit(20)/ 'T.L. [cm/source]'/
      data hsunit(21)/ 'Dose [MeV/source]'/
      data hsunit(22)/ 'Dose [MeV/source]'/
      data hsunit(23)/ 'Dose [MeV/source]'/
      data hsunit(24)/ 'Dose [MeV/source]'/
      data hsunit(25)/ 'n*f(n) [dimensionless]'/
      data hsunit(26)/ 'E*f(E) [dimensionless]'/
      data hsunit(27)/ 'y*f(y) [dimensionless]'/
      data hsunit(28)/ 'z*f(z) [dimensionless]'/
      data hsunit(29)/ 'n*d(n) [event]'/
      data hsunit(30)/ 'E*d(E) [MeV]'/
      data hsunit(31)/ 'y*d(y) [keV/um]'/
      data hsunit(32)/ 'z*d(z) [Gy]'/

      character hxunit(0:3)*12
      data hxunit(0) / 'n [Event]'/
      data hxunit(1) / 'e [MeV]'/
      data hxunit(2) / 'y [keV/um]'/
      data hxunit(3) / 'z [Gy]'/

      character cha*1
      data cha /"'"/

cfrtati 2021/10/05 chl, chm moved to partmod

cfrtati 2021/10/05 6 -> itmxpt
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31


      character rpa*1
      data rpa /'}'/
      character yen*1
      include 'samepage_include/samepage000_norm.inc'

      yen  = char(92)
      allocate( ixyz(max((nx+1)*(ny+1),(ny+1)*(nz+1),(nx+1)*(nz+1))) )

      include 'samepage_include/samepage001.inc'

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*     for igshow
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

            npg = np
            neg = ne

         else

            npg = 1
            neg = 1

         end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*           itunt(m) = 1 : cm/z/source
*                    = 2 : MeV/z/source
*                    = 3 : cm/ln(z)/source
*                    = 4 : MeV/ln(z)/source
*                    = 5 : cm/source
*                    = 6 : MeV/source
*                    = 7 : y*f(y)
*                    = 8 : y*d(y)
*           itsun(m) = 0 : Event
*                    = 1 : MeV
*                    = 2 : keV/um
*                    = 3 : Gy
*-----------------------------------------------------------------------
            if( itunt(m) .le. 2 .or. itunt(m) .eq. 7) then ! T.Sato 2017/11/21

               do i = 1, ne

                  ew(i) = ( eb(i+1) - eb(i) )

               end do
               ew_sum = ( eb(ne+1) - eb(1) )

            else if( itunt(m) .le. 4 .or. itunt(m) .eq. 8) then ! T.Sato 2017/11/21

               do i = 1, ne

                  ew(i) = log( eb(i+1) / eb(i) )

               end do
               ew_sum = log( eb(ne+1) / eb(1) )

            else

               do i = 1, ne

                  ew(i) = 1.d0

               end do
               ew_sum = 1.0d0

            end if

*-----------------------------------------------------------------------
*        set mesh volume and name
*-----------------------------------------------------------------------

               call tregvl(nr,mr,kr,vl,lr,nvl,ivl,rvl)

*-----------------------------------------------------------------------
*        vol = 1.0
*-----------------------------------------------------------------------

               do ir = 1, nr

                  vl(ir) = 1.0d0

               end do
               vl_sum = 1.0d0

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*        c1 : nomalization for source
*-----------------------------------------------------------------------

         if( igsh .eq. 0 ) then

                  cmax = 0.0
                  cmin = 1.e+33
                  dnon = 1.e-33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

               if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

                  c1 = 1.0d+0 / rsouin

               else

                  c1 = 0d0

               end if

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

               do 101 ir = 1, nr
               do 101 ie = 1, ne
               do 101 ip = 1, np

                  if( tr(ip,ie,ir,1) .gt. 0.d0 ) then

                     fmaxfc = tr(ip,ie,ir,1) / vl(ir) / ew(ie)

                     if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                  end if

  101          continue

            end if

            do 100 ir = 1, nr
            do 100 ie = 1, ne
            do 100 ip = 1, np

               if( tr(ip,ie,ir,1) .gt. 0.d0 ) then

                  call calc_stdev(m,Xa,sigx,
     &                            tr(ip,ie,ir,1),
     &                            tr(ip,ie,ir,2),
     &             abs(rtfac(m)/facmax(m))/vl(ir)/ew(ie))

                  tr(ip,ie,ir,1) = Xa
                  tr(ip,ie,ir,2) = sigx
                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ip,ie,ir,1) .gt. cmax )
     &                        cmax = tr(ip,ie,ir,1)

                  if( tr(ip,ie,ir,1) .lt. cmin )
     &                        cmin = tr(ip,ie,ir,1)

               else

                  isdz = 1
                  tr(ip,ie,ir,2) = 0.0

               end if

! sumover
               fact_in = abs(rtfac(m)/facmax(m))
               call psedreg_sumover_stdev(0,m,ip,ie,ir,
     &                fact_in,ew(ie),vl(ir),ew_sum,vl_sum)

  100       continue

            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

         end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do 900 iax = 1, itfln(m)

         if( igsh .ne. 0 .and.
     &     ( itaxs(m,iax) .lt. 7 .or. itrsh(m) .eq. 0 ) ) goto 900

         if( (itall .eq. 2 .and. nobch .lt. maxbch .and. igsh .eq. 0)
     &        .or. ( itall .eq. 4 .and. igsh .eq. 0 ) ) then

            call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &           nobch,maxbch,npe)

         else

            fname = ctfln(m,iax)

         end if

            iot = 31
            open(iot, file = fname, status = 'unknown' )

*-----------------------------------------------------------------------
            gfnam = ctfln(m,iax)
            igfmn = itfll(m,iax)
            igser = itger(m)

*-----------------------------------------------------------------------
*     input echo
*-----------------------------------------------------------------------

               call sedech(iot,m,iax,1)


      include 'samepage_include/samepage002_per_norm.inc'
      include 'samepage_include/samepagechp_per_norm.inc'
      include 'samepage_include/samepageseti.inc'

*-----------------------------------------------------------------------
*        SED axis
*-----------------------------------------------------------------------

         if( itaxs(m,iax) .eq. 1 ) then

               inum = 0

            do iri = 1, nr, nrstepi
            do ipi = 1, np, npstepi
               ir = iri
               ip = ipi

               inum = inum + 1

               ireg = lr(ir)

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

               if(iloopmode .ge. 1) then
                  write(iot,'("#   ",a)') chp(ipi)(3:10)
               endif

               write(iot,'("#   no. =",i3,3x,"reg =",i7)')
     &                     inum, ireg

               if( itaxl(m) .eq. 0 ) then

                  write(iot,'(/"x: ",a12)') hxunit(itsun(m))

               else

                  write(iot,'(/"x: ",200a1)')
     &                       (itaxt(m)(i:i),i=1,itaxl(m))

               end if

               if( itayl(m) .eq. 0 ) then

                  write(iot,'( "y: ",a30)')
     &            hsunit(4*(itunt(m)-1)+itsun(m)+1)

               else

                  write(iot,'( "y: ",200a1)')
     &                       (itayt(m)(i:i),i=1,itayl(m))

               end if

               if( itety(m) .eq. 3 .or. itety(m) .eq. 5 ) then

                  write(iot,'( "p: xlog ylog afac(0.8) form(0.9)")')

               else

                  write(iot,'( "p: xlin ylog afac(0.8) form(0.9)")')

               end if

               if( itanl(m) .gt. 0 ) then

                  write(iot,'( "p: ",200a1)')
     &            ( itang(m)(i:i),i = 1, itanl(m) )

               end if

               if( itsans(m) .gt. 0 ) then

                  call write_sangel(iot,m,0)

               end if

       include 'samepage_include/per_e_norm_sed.inc'
*-----------------------------------------------------------------------

             if(iloopmode .eq. 0) then
                     write(iot,'(/a1,"no. =",i3,
     &                        ",  reg  =",i7,a1)')
     &                        cha, inum, ireg, cha
             else
                write(changelsub(1),'(a1,"no. =",i3)') cha,inum
                write(changelsub(2),'(",  part = ",a)') chp(ipi)(3:10)
                write(changelsub(3),'(",  reg  =",i7)') ireg
                write(changelsub(4),'(",  ie =",i3)') ie
                write(changelsub(5),'(a1)') cha

               changelsub(4) = " "
               if(iloopmode .eq. 2) then
                  changelsub(3) = " "
               end if
               if(iloopmode .eq. 1) then
                  changelsub(4) = " "
               end if
