            do ie = 1, neg

               zval = ( zm(iz) + zm(iz+1) ) / 2.0d0

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 .or. ip.gt.np_mxang ) then ! frtati 2021/10/05
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
