      deallocate( ixyz )
cnais 2023/01/31
      include 'samepage_include/samepage999_norm.inc'

      return
      end


************************************************************************
*                                                                      *
      subroutine tsedrz(ncol,m,nl,lt,np,nr,nz,ne,rm,zm,eb,tr,trEVENT,
     &                  itrmax,itrmin)
*                                                                      *
*       SED tally in r-z scoring mesh                                  *
*       last modified by K.Niita on 2006/02/10                         *
*                                                                      *
*----------------------------------------------------------------------*
*                                                                      *
*      ncol  ..... reaction type                                       *
*              9 : termination by time cut-off                         *
*             10 : geometry boundary crossing                          *
*             11 : termination by energy cut-off                       *
*             12 : termination by escape or leakage                    *
*             13 : nuclear reaction (n,x)                              *
*             14 : nuclear reaction (n,n'x)                            *
*             15 : sequential transport only for tally                 *
*                                                                      *
************************************************************************
      use MMBANKMOD !FURUTA
      use partmod, only: itmxpt ! frtati 2021/10/05
      use TSEDMOD  ! T.Sato 2022/08/15
*-----------------------------------------------------------------------

      implicit double precision( a-h, o-z )

*-----------------------------------------------------------------------

      include 'param00.inc'
      include 'param.inc'

*-----------------------------------------------------------------------

      include 'zdist.inc'

      include 'err.inc'

*-----------------------------------------------------------------------

      common /icomon/ no,mat,ityp,ktyp,jtyp,mtyp,rtyp,ctyp
!$OMP THREADPRIVATE(/icomon/)
      common /wtsave/ oldwt
!$OMP THREADPRIVATE(/wtsave/)
      common /tlgeom/ iblz1,iblz2
!$OMP THREADPRIVATE(/tlgeom/)

*-----------------------------------------------------------------------

      common /clustt/ nclsts, iclusts(nnn)
!$OMP THREADPRIVATE(/clustt/)
      common /clustw/ jclusts(0:8,nnn),  qclusts(0:12,nnn)
!$OMP THREADPRIVATE(/clustw/)
      common /cntcls/ jcount(3,nnn)
!$OMP THREADPRIVATE(/cntcls/)

*-----------------------------------------------------------------------

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall08/ rtrx0(itlmax), rtry0(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall37/ itcnt(9,itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall50/ itlmt(itlmax), ite2l(itlmax)   ! CCSE 2022.08.31
      common /tall51/ eletb(2000), nlete
      common /tall57/ itsun(itlmax),rtdim(itlmax),rtucv(itlmax),
     &rtrho(itlmax),itmodel(itlmax) ! T.Sato 2022/08/14

      common /tall82/ itcnth(9,itlmax)

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

*-----------------------------------------------------------------------

      dimension   lt(nl)
      dimension rm(nr+1)
      dimension zm(nz+1)
      dimension eb(ne+1)
      dimension tr(np,ne,nr,nz,2)
      dimension trEVENT(np,ne,nr,nz)          !OBINATA(2012.9.7): as Ct
      real(8),allocatable,save:: tr0(:,:,:,:) !OBINATA(2012.9.7): as C
      dimension itrmax(4),itrmin(4)

*-----------------------------------------------------------------------

      dimension ud(3)

      data dmax  /1.0d+19/
      data dmax0 /1.0d+18/

      dimension ips(itmxpt) ! frtati 2021/10/05 6 -> itmxpt
      dimension facm(6)

      dimension   ratio(ne+1), rati2(ne+1)
      data izpoor / 0 /
      save izpoor !FURUTA
!$OMP THREADPRIVATE(izpoor)
*-----------------------------------------------------------------------

      common /paraj/ mstz(300), parz(300)

*-----------------------------------------------------------------------

      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)
      common /stat / istdev, irestart, ireschk
      common /cparm/ maxbch,maxcas

*------------------------------------------------------------------------

      common /spred/ nspred, nwsprd, nedisp, itstep, ndedx

      common /cntmx/ ncntmx(3), nctmxsr(3)
!$OMP THREADPRIVATE(/cntmx/)

*-----------------------------------------------------------------------

            small = parz(28) * 10.d0

*-----------------------------------------------------------------------

      if (istdev .eq. 2) then
        call readitrminmax4(itrmin,itrmax,(/ np,ne,nr,nz /),
     &                      mnp,mne,mnr,mnz,
     &                      mxp,mxe,mxr,mxz)
      endif

*-----------------------------------------------------------------------
* check of history counter
*-----------------------------------------------------------------------
      ihistcount = 0 ! history counter index, T.Sato 2022/12/20 for speed up
         if ( ncol.eq.0 .or. ncol.eq.4 ) then
           do i = 1, 3
             if( itcnth(i,m) .eq. 1 ) then
               if( ncntmx(i) .lt. itcnth(i*2+2,m) .or.
     &             ncntmx(i) .gt. itcnth(i*2+3,m) ) then
 !                trEVENT = 0.d0
                 ihistcount = 1
               end if
             end if
           end do
         end if

*-----------------------------------------------------------------------
*        source particle or end of batch ( in case of istdev = 2 )
*
* OBINATA(2012.9.7): change tr(,,,,3) to trEVENT(,,,,)
*-----------------------------------------------------------------------

         if (( ncol .eq. 0 .or. ncol .eq. 4 )
     &                              .and. istdev .eq. 2) then
 !          if ( nocas .gt. 1 .or. ncol .eq. 0 ) then
           if ((nocas.gt.1.or.ncol.eq.0) .and. ihistcount.ne.1 ) then

             do iz = mnz,mxz
             do ir = mnr,mxr
               tr(:,:,ir,iz,1) = tr(:,:,ir,iz,1) + trEVENT(:,:,ir,iz)
               tr(:,:,ir,iz,2) = tr(:,:,ir,iz,2) + trEVENT(:,:,ir,iz)**2
             enddo
             enddo

! sumover
             call tsedrz_sumover(m,1,
     &                   np,  ne, nr, nz, trEVENT)


           end if

           do iz = mnz,mxz
           do ir = mnr,mxr
             trEVENT(:,:,ir,iz) = 0
           enddo
           enddo

           call resetitrminmax(itrmin,itrmax,4,(/np,ne,nr,nz/))

         end if

*-----------------------------------------------------------------------
*        end of batch ( in case of istdev = 1 )
*
* OBINATA(2012.9.7): modificate for thread parallel
*-----------------------------------------------------------------------

         if ( ncol .eq. 0 .and. istdev .eq. 1) then
!$OMP MASTER
             allocate( tr0(np,ne,nr,nz) )
             tr0(:,:,:,:) = 0.d0
!$OMP END MASTER
!$OMP BARRIER
!$OMP CRITICAL (tsedrz_crit_ist1)
             tr0(:,:,:,:) = tr0(:,:,:,:) + trEVENT(:,:,:,:)
!$OMP END CRITICAL (tsedrz_crit_ist1)
!$OMP BARRIER
!$OMP MASTER
             tr(:,:,:,:,1) = tr(:,:,:,:,1) + tr0(:,:,:,:) / maxcas
             tr(:,:,:,:,2) = tr(:,:,:,:,2)
     &                     + ( tr0(:,:,:,:) / maxcas ) ** 2
! sumover
             call tsedrz_sumover(m,maxcas,
     &                   np,  ne, nr, nz, tr0)

             deallocate( tr0 )
!$OMP END MASTER

           trEVENT(:,:,:,:) = 0

         end if

*-----------------------------------------------------------------------
*        check of ncol
*-----------------------------------------------------------------------

         if( ncol .lt. 9 ) return

*-----------------------------------------------------------------------
*        check of mat
*-----------------------------------------------------------------------

            if( nl .gt. 0 ) then

                  do i = 1, nl

                     if( itmcn(m) .gt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) goto 502
                     if( itmcn(m) .lt. 0 .and.
     &                   idmn(mat) .eq. lt(i) ) return

                  end do

                     if( itmcn(m) .gt. 0 ) return

            end if

  502          continue

*-----------------------------------------------------------------------
*        material for LET
*-----------------------------------------------------------------------

               if( itlmt(m) .gt. 0 ) then

                  lmat = idnm( itlmt(m) )

               else if( itlmt(m) .eq. 0 ) then

                  lmat = mat

               else

                  lmat = -idnm( -itlmt(m) )

               end if

*-----------------------------------------------------------------------
*        transform positions
*-----------------------------------------------------------------------

            call trnsxx(x(ibkx+no,ipomp+1),y(ibky+no,ipomp+1),
     &                  z(ibkz+no,ipomp+1),
     &                  xxa,yya,zza,itmtr(m,4))

            call trnsxx(xc(ibkxc+no,ipomp+1),yc(ibkyc+no,ipomp+1),
     &                  zc(ibkzc+no,ipomp+1),
     &                  xxc,yyc,zzc,itmtr(m,4))

*-----------------------------------------------------------------------
*        check z mesh and r mesh region
*-----------------------------------------------------------------------

               x0 = rtrx0(m)
               y0 = rtry0(m)

            if( zza-small .lt. zm(1) .and.
     &          zzc-small .lt. zm(1) ) return

            if( zza+small .ge. zm(nz+1) .and.
     &          zzc+small .ge. zm(nz+1) ) return

               dis0 = sqrt( ( xxa - x0 )**2
     &                    + ( yya - y0 )**2 )

               dis1 = sqrt( ( xxc - x0 )**2
     &                    + ( yyc - y0 )**2 )

            if( dis0 .lt. rm(1) .and.
     &          dis1 .lt. rm(1) ) return

            if( dis0 .ge. rm(nr+1) .and.
     &          dis1 .ge. rm(nr+1) ) then

               aa =   yyc - yya
               bb = - xxc + xxa
               cc = - aa * xxa - bb * yya

               if( aa**2 + bb**2 .ne. 0.0d0 ) then

                  dd = abs( aa * x0 + bb * y0 + cc )
     &               / sqrt( aa**2 + bb**2 )

                  if( dd .ge. rm(nr+1) ) return

               end if

            end if

*-----------------------------------------------------------------------
*        check of particles, only charged particles
*-----------------------------------------------------------------------

               if( jtyp .eq. 0 ) goto 200

            call pcheck(m,np,ityp,ktyp,jtyp,ipn,ips)

               if( ipn .eq. 0 ) goto 200

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( ncnt(ibknct+i,no,ipomp+1) .lt. itcnt(i*2+2,m) .or.
     &                ncnt(ibknct+i,no,ipomp+1) .gt. itcnt(i*2+3,m) )
     &                goto 200

               end if

            end do

*-----------------------------------------------------------------------
*        distance and unit vector ud(i)
*-----------------------------------------------------------------------

            dis = ( xxc - xxa )**2
     &          + ( yyc - yya )**2
     &          + ( zzc - zza )**2

            if( dis .le. small**2 ) return

            dis = sqrt(dis)

            ud(1) = ( xxc - xxa ) / dis
            ud(2) = ( yyc - yya ) / dis
            ud(3) = ( zzc - zza ) / dis

*-----------------------------------------------------------------------
*     initial position, energy and initial range rng
*-----------------------------------------------------------------------

            tot = 0.0d0
            rng1 = 0.0d0

            se  = e(ibke+no,ipomp+1)
            xpp = xxa
            ypp = yya
            zpp = zza

            if(  mat .gt. 0 )
     &          call rainge(se,rng,mat,ityp,ktyp,jtyp,rtyp)

*-----------------------------------------------------------------------
*     initial z-position
*-----------------------------------------------------------------------

               izm = 0
               izc = 0

            if( ud(3) .gt. 0.0d0 ) izk =  1
            if( ud(3) .eq. 0.0d0 ) izk =  0
            if( ud(3) .lt. 0.0d0 ) izk = -1

            if( izk .ge. 0 ) then

               do i = 1, nz + 1
                  if( zm(i) .gt. zpp + small ) then
                         izm = i - 1
                         izc = i - 1
                         goto 38
                  end if
               end do

            else

               izm = nz + 2
               izc = nz + 1

               do i = 1, nz + 1
                  if( zm(i) .ge. zpp - small ) then
                         izm = i
                         izc = i - 1
                         goto 38
                  end if
               end do

            end if

   38       continue

*-----------------------------------------------------------------------
*     initial r-position
*-----------------------------------------------------------------------

               uvec = ( xxa - x0 ) * ud(1) + ( yya - y0 ) * ud(2)

            if( uvec .ge. 0.0d0 ) then

               do i = 1, nr + 1
                  if( rm(i) .gt. dis0 + small ) then
                        irc = i - 1
                        goto 47
                  end if
               end do

            else

               do i = 1, nr + 1
                  if( rm(i) .ge. dis0 - small ) then
                        irc = i - 1
                        goto 47
                  end if
               end do

            end if

                  irc = nr + 1

   47          continue

*-----------------------------------------------------------------------
*     loop for finding mesh and booking upto total distance
*-----------------------------------------------------------------------

      do 50

*-----------------------------------------------------------------------
*      calculation is finished
*-----------------------------------------------------------------------

         if( tot .ge. dis ) goto 200

*-----------------------------------------------------------------------
*        check of energy
*-----------------------------------------------------------------------

         if( se .lt. eletb(1) ) goto 200

*-----------------------------------------------------------------------
*        dr : distance to the nearest r mesh
*-----------------------------------------------------------------------

               dr = dmax

               a  = ud(1)**2 + ud(2)**2

         if( a .gt. 0.0d0 ) then

               b = 2.0d0 * ( ud(1) * ( xpp - x0 )
     &                     + ud(2) * ( ypp - y0 ) )

               ir1 = irc
               ir2 = irc + 1

              if( b .ge. 0.0 ) ir1 = irc + 1

            do 51 i = max( 1, ir1 ), min( nr + 1, ir2 )

               if( rm(i) .eq. 0.0d0 ) goto 51

               c = ( xpp - x0 )**2
     &           + ( ypp - y0 )**2 - rm(i)**2

               dchk = b**2 - 4.0d0 * a * c

               if( dchk .lt. 0.0d0 ) goto 51

               t1 = ( -b + sqrt(dchk) ) / ( a * 2.0 )
               t2 = ( -b - sqrt(dchk) ) / ( a * 2.0 )

               if( t1 .lt. small ) t1 = dmax
               if( t2 .lt. small ) t2 = dmax

               ttr = min(t1,t2)

               if( ttr .lt. dr ) then

                  dr  = ttr
                  idr = i

               end if

   51       continue

         end if

*-----------------------------------------------------------------------
*        dz : distance to the nearest z mesh
*-----------------------------------------------------------------------

               dz = dmax

         if( izk .ne. 0 ) then
            if( izm + izk .ge. 1 .and.
     &          izm + izk .le. nz + 1 ) then

               dz = abs( ( zm(izm+izk) - zpp ) / ud(3) )

            end if
         end if

*-----------------------------------------------------------------------
*        which boundary is the nearlist
*-----------------------------------------------------------------------

            if( dr .gt. dz ) then

               dd = dz
               jz = 1

            else

               dd = dr
               jz = 0

            end if

            if( dd .gt. dmax0 ) return

*-----------------------------------------------------------------------
*        recalculate rng for ncol = 11 and nedisp
*-----------------------------------------------------------------------

            if( mat .gt. 0 .and. jtyp .ne. 0 .and. nedisp .ne. 0 .and.
     &           (  ityp .ne. 12 .and. ityp .ne. 13 ) ) then

               call rainge(se,rng,mat,ityp,ktyp,jtyp,rtyp)

               if( ncol .eq. 11 )  dis = tot + rng

            end if

*-----------------------------------------------------------------------
*        propagate position upto the boundary or the final point
*-----------------------------------------------------------------------

            if( tot + dd .ge. dis - small ) then

               dd  = dis - tot
               tot = dis
               xpp = xxc
               ypp = yyc
               zpp = zzc

            else

               tot = tot + dd
               xpp = xpp + dd * ud(1)
               ypp = ypp + dd * ud(2)
               zpp = zpp + dd * ud(3)

            end if

*-----------------------------------------------------------------------
*        final energy ee and range rng1
*-----------------------------------------------------------------------

            if( mat .gt. 0 ) then

               delt = dd

               call ecol(ee,delt,se,rng,
     &                   mat,ityp,ktyp,jtyp,rtyp)

               rng1 = max( 0.0d0, rng - delt )

               if( rng1 .gt. 1.d+30 ) goto 200

               ee = max( 0.0d0, ee )
               ee = min( se, ee )

            else

               ee = se

            end if

*-----------------------------------------------------------------------
*        booking
*-----------------------------------------------------------------------

            iz = izc
            ir = irc

         if( ir .ge. 1 .and. ir .lt. nr + 1 .and.
     &       iz .ge. 1 .and. iz .lt. nz + 1 ) then

*-----------------------------------------------------------------------
*           initial and final energy cell
*-----------------------------------------------------------------------

               do i = 1, nlete

                  if( se .ge. eletb(i) .and.
     &                se .lt. eletb(i+1) ) goto 30

               end do

   30             ie1 = min( i, nlete )

               do i = nlete, 1, -1

                  if( ee .ge. eletb(i) .and.
     &                ee .lt. eletb(i+1) ) goto 40

               end do

   40             ie2 = max( i, 1 )

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

                  rrl = dd
                  rrr = dd
                  rrt = 0.0d0

            if( mat .gt. 0 ) then

               if( se .gt. eletb(nlete+1) ) then

                  call rainge(eletb(nlete+1),rngm,mat,
     &                        ityp,ktyp,jtyp,rtyp)

                  rrr = max( 0.0d0, rrr - ( rng - rngm ) )
                  rrt = rrt + rng -rngm

               end if

            end if

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 270 ie = ie1, ie2, -1

                     emie = max( ee, eletb(ie) )
                     emiu = min( se, eletb(ie+1) )
                  if( emiu * emie .gt. 0.d0 ) then
                     erg  = sqrt( emiu * emie )
                  else
                     erg  = emiu / 2.d0
                  end if
                     eff  = emiu - emie

                  if( mat .gt. 0 ) then

                     call rainge(emie,rng2,mat,ityp,ktyp,jtyp,rtyp)

                     rng2 = max( 0.0d0, rng2 - rng1 )
                     rrl  = max( 0.0d0, rrr  - rng2 )

                        rrt  = rrt + rrl

                     if( rrt .gt. dd ) then

                        rrl = rrl + ( dd - rrt )
                        rrt = dd

                     else if( ie .eq. ie2 .and.
     &                        ee .gt. eletb(ie) ) then

                        rrl = rrl + ( dd - rrt )

                     end if

                  end if

*-----------------------------------------------------------------------
*              LET bin
*-----------------------------------------------------------------------

               call dedxas(erg,dedx,lmat,ityp,ktyp,jtyp,rtyp)

                  dedx = dedx / 10.d0

                  if( itunt(m) .eq. 1 .or. itunt(m) .eq. 3 .or.
     &                itunt(m) .eq. 5 ) then

                        tlv0 = oldwt * rrl

                  else

                        tlv0 = oldwt * eff

               if( ( ityp.eq.12 .or. ityp.eq.13 .or. ityp.eq.14 ) .and.
     &         (ncol.eq.9.or.ncol.eq.11).and.ie.eq.ie2)
     &         tlv0 = tlv0 + oldwt*erg  ! T.Sato 2022/08/17, add cut-off energy

                  end if

*-----------------------------------------------------------------------

                 if(dedx .le. 1.0e-6) goto 264

                     CelDiam   = abs(rtdim(m))  ! T.Sato 2021/10/07

                     unitconv  = rtucv(m)

                  if( ityp .eq. 12 .or. ityp .eq. 13 .or.
     &                ityp .eq.  6 .or. ityp .eq.  7 ) then

                   if(itmodel(m).ge.1) then
                    if((ncol.eq.9.or.ncol.eq.11).and.ie.eq.ie2) then ! stopped electron
                     call getAparastp(rtdim(m)*rtrho(m),erg,itmodel(m))
                    else
                     call getAparaele(rtdim(m)*rtrho(m),erg,itmodel(m))
                    endif
                    depev=0.0 ! not used for electron mode
                   else
                     call getfitele(CelDiam*rtrho(m),erg)
                   endif

                  else

                     izz = abs(jtyp)
                     if( izz .gt. 26 ) izz = 26

                     AA = 1.0
                     if( ityp .ge. 15 )
     &               AA = dble( ktyp - ktyp / 1000000 * 1000000 )

                 if(itmodel(m).ge.1) then
                   depev=min(dedx*CelDiam*1.0e3,erg*1.0d6)  ! max deposition energy in eV
                   call getAparaion(CelDiam*rtrho(m),erg/AA,izz,
     &             depev,itmodel(m))
                 else
                   call getfit(CelDiam*rtrho(m),izz,erg/AA,dedx*10.0)
                 endif

                  end if

                     do i = 1, ne + 1
                        ratio(i) = 0.0
                        rati2(i) = 0.0
                     end do

        if(itmodel(m).ge.1) then ! new model 2022/08/16

         tmp=sedmean(1.0d0,depev) ! get Apara(9)
         if(itsun(m).eq.0) then ! number of event
          factor=1.0d0
         else  ! convert MeV to number of event
          factor=1.0e6/Apara(9)
         endif

         do i = 1, ne

          zlow = factor*unitconv *   eb(i)   ! number of event
          zhig = factor*unitconv *   eb(i+1)
          zwid = factor*unitconv * ( eb(i+1) - eb(i) )
          zmid = factor*unitconv * ( eb(i+1) + eb(i) ) / 2.d0

          zdfzmzw = zmid*sedmean(zmid,depev) * zwid  ! zf(z)dz
          ratio(i) = zdfzmzw
          rati2(i) = zdfzmzw/zmid

          ratio(ne+1) = ratio(ne+1) + ratio(i)
          rati2(ne+1) = rati2(ne+1) + rati2(i)

         enddo

        else ! old model

                  tmpcomp=Ccurr(1)*100.0
                  if(tmpcomp .le. 5.0e-3) tmpcomp=5.0e-3

                  do i = 1, ne

                     zlow = unitconv *   eb(i)
                     zhig = unitconv *   eb(i+1)
                     zwid = unitconv * ( eb(i+1) - eb(i) )
                     zmid = unitconv * ( eb(i+1) + eb(i) ) / 2.d0

                     zmidi = 1.d0 / zmid

                     if( zmid .gt. tmpcomp ) goto 777

                     if( zhig .lt. Pmid(iponly) ) then

                        ratio(i) = Pcurr(1) / Pmid(iponly) * zwid
                        rati2(i) = Pcurr(1) / Pmid(iponly) * zwid*zmidi

                     else

                      if(rtdim(m).ge.0) then  ! T.Sato 2021/10/07, consider Auger contribution

                        do ip = iponly, npeak-1

                           if(zlow .le. Pmid(ip) .and.
     &                        zhig .gt. Pmid(ip) ) then

                              ratio(i) = ratio(i) + Pcurr(ip)
                              rati2(i) = rati2(i) + Pcurr(ip) * zmidi

                           end if

                        end do

                        if(zlow .le. Pmid(npeak) .and.
     &                     zhig .gt. Pmid(npeak) ) then

                           z0 = Pmid(npeak)

                           Auger(0)=(Gau(zlow-z0,Wauger)+1)*abs(zlow-z0)
     &                             +(Gau(zhig-z0,Wauger)+1)*abs(zhig-z0)

                           Atotal=Auger(0)

                           kmin = max(   1-i,-maxAuger+1)
                           kmax = min(ne-1-i, maxAuger-1)

                           do k = -1,kmin,-1

                              zl = unitconv *   eb(i+k)
                              zh = unitconv *   eb(i+k+1)

                              Auger(k)=(Gau(zl-z0,Wauger)
     &                        +Gau(zh-z0,Wauger))*(zh-zl)

                              Atotal = Atotal + Auger(k)

                              if(Auger(k).le.Auger(0)*1.0e-2) goto 333

                           end do

 333                       ilow = k

                           do k = 1,kmax

                              zl = unitconv *   eb(i+k)
                              zh = unitconv *   eb(i+k+1)

                              Auger(k)=(Gau(zl-z0,Wauger)
     &                        +Gau(zh-z0,Wauger))*(zh-zl)

                              Atotal = Atotal + Auger(k)

                              if(Auger(k).le.Auger(0)*1.0e-2) goto 444

                           end do

 444                       ihig = k

                           do k = ilow, ihig

                              zmm = unitconv*(eb(i+k)+eb(i+k+1))*0.5

                              ratio(i+k) = ratio(i+k) + Pcurr(npeak)
     &                        * Auger(k)/Atotal
                              rati2(i+k) = rati2(i+k) + Pcurr(npeak)
     &                        * Auger(k)/Atotal / zmm

                           end do

                        end if

                      else  ! ignore Auger contribution

                        do ip = iponly, npeak-2

                           if(zlow .le. Pmid(ip) .and.
     &                        zhig .gt. Pmid(ip) ) then

                              ratio(i) = ratio(i) + Pcurr(ip)
                              rati2(i) = rati2(i) + Pcurr(ip) * zmidi

                           end if

                        end do

                      endif

                      zdfzmzw = zdistfunc(zmid) * zwid
                      ratio(i) = ratio(i) + zdfzmzw
                      rati2(i) = rati2(i) + zdfzmzw*zmidi

                     end if

                     ratio(ne+1) = ratio(ne+1) + ratio(i)
                     rati2(ne+1) = rati2(ne+1) + rati2(i)

                  end do

  777             if( ratio(ne+1) .lt. 0.5) then

                     write(ErrCha,*) 'Warning: Z bin is not enough !',
     &               ratio(ne+1)
                     ErrID = 'L:23449/R:tsedrz/F:talls07.f' !W61_001_003
                     call ErrWrite(ErrID,ErrCha)

                     if( ratio(ne+1) .eq. 0.0) ratio(ne+1)=1.0

                     izpoor = izpoor + 1
                     if( izpoor .gt. 10 ) then
                        write(ErrCha,*) 'Too poor of Z bin !!!'
                        ErrID = 'L:23457/R:tsedrz/F:talls07.f' !E61_002_003
                        call ErrWrite(ErrID,ErrCha)
                        call parastop( 666 )
                     end if

                  end if

              endif ! end of old model

                  if( itunt(m) .eq. 1 .or. itunt(m) .eq. 3 .or.
     &                itunt(m) .eq. 5 ) then

                      do i = 1, ne

! nais
                        if(rati2(ne+1) .ne. 0.0d0) then
                          tlv = tlv0 * rati2(i) / rati2(ne+1)
                        else
                          tlv = 0.0d0
                        endif
                        tlv = max(0.d0,tlv)

                         do ip = 1, ipn
                            trEVENT(ips(ip),i,ir,iz) =
     &                      trEVENT(ips(ip),i,ir,iz) + tlv
                         end do

                      end do

                  else

                      do i = 1, ne

! nais
                        if(ratio(ne+1) .ne. 0.0d0) then
                          tlv = tlv0 * ratio(i) / ratio(ne+1)
                        else
                          tlv = 0.0d0
                        endif

                        tlv = max(0.d0,tlv)

                         do ip = 1, ipn
                            trEVENT(ips(ip),i,ir,iz) =
     &                      trEVENT(ips(ip),i,ir,iz) + tlv
                         end do

                      end do

                  end if

                  if (istdev .eq. 2) then
                    call setitrminmax(itrmin,itrmax,3,4,
     &                               (/ir,iz/))
                  endif

*-----------------------------------------------------------------------

  264             rrr = rrr - rrl

  270       continue

*-----------------------------------------------------------------------

         end if

*-----------------------------------------------------------------------
*     next position
*     for z-crossing jz = 1, r-crossing jz = 0
*-----------------------------------------------------------------------

            if( jz .eq. 1 ) then

                  izm = izm + izk
                  izc = izc + izk

            else if( jz .eq. 0 ) then

               if( idr .gt. irc ) then

                  irc = idr

               else

                  irc = idr - 1

               end if

            end if

            se  = ee
            rng = rng1

*-----------------------------------------------------------------------

   50 continue

*-----------------------------------------------------------------------

  200       continue

*-----------------------------------------------------------------------
*     dead particles of produced charged particle
*-----------------------------------------------------------------------

      if( ( ncol .eq. 13 .or. ncol .eq. 14 ) .and.
     &      mat .gt. 0 .and. nclsts .gt. 0 ) then

*-----------------------------------------------------------------------
*        check of counter
*-----------------------------------------------------------------------

            do i = 1, 3

               if( itcnt(i,m) .ne. 0 ) then

                  if( jcount(i,1) .lt. itcnt(i*2+2,m) .or.
     &                jcount(i,1) .gt. itcnt(i*2+3,m) ) return

               end if

            end do

*-----------------------------------------------------------------------
*        check z mesh and r mesh region
*-----------------------------------------------------------------------

            if(  zzc .lt. zm(1) ) return
            if(  zzc .ge. zm(nz+1) ) return
            if( dis1 .lt. rm(1) ) return
            if( dis1 .ge. rm(nr + 1) ) return

*-----------------------------------------------------------------------
*           z-position
*-----------------------------------------------------------------------

               do i = 1, nz

                  if( zzc .ge. zm(i) .and.
     &                zzc .lt. zm(i+1) ) goto 39

               end do

   39          iz = i

*-----------------------------------------------------------------------
*           r-position
*-----------------------------------------------------------------------

               do i = 1, nr

                  if( dis1 .ge. rm(i) .and.
     &                dis1 .lt. rm(i+1) ) goto 48

               end do

   48          ir = i

*-----------------------------------------------------------------------
*        dead particle and nucleus
*-----------------------------------------------------------------------

         do j = 1, nclsts

         if( jclusts(4,j) .lt. 0 .and. jclusts(5,j) .ne. 0 .and.
     &       qclusts(7,j) .gt. eletb(1) ) then


                  ipart = jclusts(3,j)
                  kpart = jclusts(7,j)
                  jpart = jclusts(5,j)
                  rpart = qclusts(5,j) * 1000.d0

*-----------------------------------------------------------------------

            call pcheck(m,np,ipart,kpart,jpart,ipn,ips)

               if( ipn .eq. 0 )  goto 285

           if( itunt(m) .eq. 1 .or. itunt(m) .eq. 3 .or.
     &         itunt(m) .eq. 5 ) goto 285  ! T.Sato 2022/08/19, not necessary to consider dead particle for track length mode

*-----------------------------------------------------------------------

                  ein = qclusts(7,j)
                  ecc = 0.0d0

               if( ein .lt. eletb(1) ) goto 285

*-----------------------------------------------------------------------

             if(ipart.ge.12.and.ipart.le.14) then ! for electron, positron, photon, T.Sato 2022/08/19
               ie1=1
               ie2=1
               tlv0=ein*qclusts(8,j)
               erg=tlv0
             else

               do i = 1, nlete

                  if( ein .ge. eletb(i) .and.
     &                ein .lt. eletb(i+1) ) goto 35

               end do

   35             ie1 = min( i, nlete )
                  ie2 = 1

*-----------------------------------------------------------------------
*           rrl : track length and rrr : charge particles correction
*-----------------------------------------------------------------------

                  call rainge(ein,rng0,mat,
     &                        ipart,kpart,jpart,rpart)

! T.Sato 2015/2/27, electron and positrons are OK when rng0 > 1.d30
                  if( abs(kpart).ne.11.and.rng0.gt.1.d+30) goto 285


                  tlngth = rng0
                  rng1 = 0.0d0

                  rrl = tlngth
                  rrr = tlngth
                  rrt = 0.0d0

               if( ein .gt. eletb(nlete+1) ) then

                  call rainge(eletb(nlete+1),rngm,mat,
     &                        ipart,kpart,jpart,rpart)

                  rrr = max( 0.0d0, rrr - ( rng0 - rngm ) )
                  rrt = rrt + rng0 -rngm

               end if

            endif

*-----------------------------------------------------------------------
*        tally
*-----------------------------------------------------------------------

            do 275 ie = ie1, ie2, -1

             if(ipart.ge.12.and.ipart.le.14) goto 276  ! T.Sato 2022/08/19

                     emie = max( ecc, eletb(ie) )
                     emiu = min( ein, eletb(ie+1) )
                  if( emiu * emie .gt. 0.d0 ) then
                     erg  = sqrt( emiu * emie )
                  else
                     erg  = emiu / 2.d0
                  end if
                     eff  = emiu - emie

                  if( mat .gt. 0 ) then

                     call rainge(emie,rng,mat,
     &                           ipart,kpart,jpart,rpart)

                     rng = max( 0.0d0, rng - rng1 )
                     rrl = max( 0.0d0, rrr - rng )

                        rrt  = rrt + rrl

                     if( rrt .gt. tlngth ) then

                        rrl = rrl + ( tlngth - rrt )
                        rrt = tlngth

                     else if( ie .eq. ie2 .and.
     &                        ecc .gt. eletb(ie) ) then

                        rrl = rrl + ( tlngth - rrt )

                     end if

                  end if

*-----------------------------------------------------------------------
*              LET bin
*-----------------------------------------------------------------------

               call dedxas(erg,dedx,lmat,ipart,kpart,jpart,rpart)

                  dedx = dedx / 10.d0

                        tlv0 = qclusts(8,j) * eff

*-----------------------------------------------------------------------

                 if(dedx .le. 1.0e-6) goto 265

 276                 CelDiam   = abs(rtdim(m))  ! T.Sato 2021/10/07
                     unitconv  = rtucv(m)

cTS2012/5/11 jtyp->jpart, ityp->ipart, ktyp->kpart

                  if( ipart .eq. 12 .or. ipart .eq. 13 .or.
     &                ipart .eq.  6 .or. ipart .eq.  7 ) then

                   if(itmodel(m).ge.1) then
                     call getAparastp(rtdim(m)*rtrho(m),erg,itmodel(m))
                     depev=0.0 ! not used for electron mode
                   else
                     call getfitele(CelDiam*rtrho(m),erg)
                   endif

                  else

                     izz = abs(jpart)
                     if( izz .gt. 26 ) izz = 26

                     AA = 1.0
                     if( ipart .ge. 15 )
     &               AA = dble( kpart - kpart / 1000000 * 1000000 )

                 if(itmodel(m).ge.1) then
                   depev=min(dedx*CelDiam*1.0e3,erg*1.0d6)  ! max deposition energy in eV
                   call getAparaion(CelDiam*rtrho(m),erg/AA,izz,
     &             depev,itmodel(m))
                 else
                   call getfit(CelDiam*rtrho(m),izz,erg/AA,dedx*10.0)
                 endif

                  end if

                     do i = 1, ne + 1
                        ratio(i) = 0.0
                        rati2(i) = 0.0
                     end do

        if(itmodel(m).ge.1) then ! new model 2022/08/16

         tmp=sedmean(1.0d0,depev) ! temporary call to get Apara(9)
         if(itsun(m).eq.0) then ! number of event
          factor=1.0d0
         else  ! convert MeV to number of event
          factor=1.0e6/Apara(9)
         endif

         do i = 1, ne

          zlow = factor*unitconv *   eb(i)   ! number of event
          zhig = factor*unitconv *   eb(i+1)
          zwid = factor*unitconv * ( eb(i+1) - eb(i) )
          zmid = factor*unitconv * ( eb(i+1) + eb(i) ) / 2.d0

          zdfzmzw = zmid*sedmean(zmid,depev) * zwid  ! zf(z)dz
          ratio(i) = zdfzmzw
          rati2(i) = zdfzmzw/zmid

          ratio(ne+1) = ratio(ne+1) + ratio(i)
          rati2(ne+1) = rati2(ne+1) + rati2(i)

         enddo

        else ! old model

                  do i = 1, ne

                     zlow = unitconv *   eb(i)
                     zhig = unitconv *   eb(i+1)
                     zwid = unitconv * ( eb(i+1) - eb(i) )
                     zmid = unitconv * ( eb(i+1) + eb(i) ) / 2.d0

                     zmidi = 1.d0 / zmid

                     tmpcomp=Ccurr(1)*100.0
                     if(tmpcomp .le. 5.0e-3) tmpcomp=5.0e-3
                     if( zmid .gt. tmpcomp ) goto 888

                     if( zhig .lt. Pmid(iponly) ) then

                        ratio(i) = Pcurr(1) / Pmid(iponly) * zwid
                        rati2(i) = Pcurr(1) / Pmid(iponly) * zwid*zmidi

                     else

                      if(rtdim(m).ge.0) then  ! T.Sato 2021/10/07, consider Auger contribution

                        do ip = iponly, npeak-1

                           if(zlow .le. Pmid(ip) .and.
     &                        zhig .gt. Pmid(ip) ) then

                              ratio(i) = ratio(i) + Pcurr(ip)
                              rati2(i) = rati2(i) + Pcurr(ip) * zmidi

                           end if

                        end do

                        if(zlow .le. Pmid(npeak) .and.
     &                     zhig .gt. Pmid(npeak) ) then

                           z0 = Pmid(npeak)

                           Auger(0)=(Gau(zlow-z0,Wauger)+1)*abs(zlow-z0)
     &                             +(Gau(zhig-z0,Wauger)+1)*abs(zhig-z0)

                           Atotal=Auger(0)

                           kmin = max(   1-i,-maxAuger+1)
                           kmax = min(ne-1-i, maxAuger-1)

                           do k = -1,kmin,-1

                              zl = unitconv *   eb(i+k)
                              zh = unitconv *   eb(i+k+1)

                              Auger(k)=(Gau(zl-z0,Wauger)
     &                        +Gau(zh-z0,Wauger))*(zh-zl)

                              Atotal = Atotal + Auger(k)

                              if(Auger(k).le.Auger(0)*1.0e-2) goto 334

                           end do

 334                       ilow = k

                           do k = 1,kmax

                              zl = unitconv *   eb(i+k)
                              zh = unitconv *   eb(i+k+1)

                              Auger(k)=(Gau(zl-z0,Wauger)
     &                        +Gau(zh-z0,Wauger))*(zh-zl)

                              Atotal = Atotal + Auger(k)

                              if(Auger(k).le.Auger(0)*1.0e-2) goto 445

                           end do

 445                       ihig = k

                           do k = ilow, ihig

                              zmm = unitconv*(eb(i+k)+eb(i+k+1))*0.5

                              ratio(i+k) = ratio(i+k) + Pcurr(npeak)
     &                        * Auger(k)/Atotal
                              rati2(i+k) = rati2(i+k) + Pcurr(npeak)
     &                        * Auger(k)/Atotal / zmm

                           end do

                        end if

                      else  ! ignore Auger contribution

                        do ip = iponly, npeak-2

                           if(zlow .le. Pmid(ip) .and.
     &                        zhig .gt. Pmid(ip) ) then

                              ratio(i) = ratio(i) + Pcurr(ip)
                              rati2(i) = rati2(i) + Pcurr(ip) * zmidi

                           end if

                        end do

                      endif

                      zdfzmzw = zdistfunc(zmid) * zwid
                      ratio(i) = ratio(i) + zdfzmzw
                      rati2(i) = rati2(i) + zdfzmzw*zmidi

                     end if

                     ratio(ne+1) = ratio(ne+1) + ratio(i)
                     rati2(ne+1) = rati2(ne+1) + rati2(i)

                  end do

  888             if( ratio(ne+1) .lt. 0.5) then

                     write(ErrCha,*) 'Warning: Z bin is not enough !'
                     ErrID = 'L:23938/R:tsedrz/F:talls07.f' !W61_001_004
                     call ErrWrite(ErrID,ErrCha)

                     if( ratio(ne+1) .eq. 0.0) ratio(ne+1)=1.0

                     izpoor = izpoor + 1
                     if( izpoor .gt. 1000 ) then
                      write(ErrCha,*) 'Too poor of Z bin !!!'
                      ErrID = 'L:23946/R:tsedrz/F:talls07.f' !E61_002_004
                      call ErrWrite(ErrID,ErrCha)
                      call parastop( 666 )
                     end if

                  end if
            endif ! end of old model

                    do i = 1, ne

! nais
                      if(ratio(ne+1) .ne. 0.0d0) then
                        tlv = tlv0 * ratio(i) / ratio(ne+1)
                      else
                        tlv = 0.0d0
                      endif

                      tlv = max(0.d0,tlv)

                      do ip = 1, ipn
                         trEVENT(ips(ip),i,ir,iz) =
     &                   trEVENT(ips(ip),i,ir,iz) + tlv
                      end do

                    end do


                  if (istdev .eq. 2) then
                    call setitrminmax(itrmin,itrmax,3,4,
     &                               (/ir,iz/))
                  endif

*-----------------------------------------------------------------------

  265       continue

            if(ipart.lt.12.or.ipart.gt.14)  rrr = rrr - rrl

  275       continue

*-----------------------------------------------------------------------

  285       continue

         end if
         end do

      end if

*-----------------------------------------------------------------------

      return
      end


************************************************************************
*                                                                      *
      subroutine psedrz(m,np,nr,nz,ne,rm,zm,eb,
     &                  tr,idasa)
*                                                                      *
*       output r-z scoring mesh SED tally                              *
*       last modified by K.Niita on 2006/02/10                         *
*                                                                      *
************************************************************************
      use sangelmod, only: itsans
      use partmod ! frtati 2021/10/05

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'param.inc'

*-----------------------------------------------------------------------

      common /taliin/ rsouin, nzztin, nrgnin

*-----------------------------------------------------------------------

      common /verjam/ versn, lastr, iyeav, imonv, idayv

      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80
      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall21/ rtfac(itlmax)
      common /tall35/ iteps(itlmax)

      common /tall57/ itsun(itlmax),rtdim(itlmax),rtucv(itlmax),
     &rtrho(itlmax),itmodel(itlmax) ! T.Sato 2022/08/14

      common /istcut/ ist_cut, ist_bat

      common /fact01/ facmax(itlmax) ! kitamura23/03/31

*-----------------------------------------------------------------------

      common /tcntl/  icntl, inucr

*-----------------------------------------------------------------------

      common /cparm/  maxbch,maxcas
      common /jcomon/ nabov,nobch,nocas,nomax
!$OMP THREADPRIVATE(/jcomon/)

      common /talout/ itall

      character fname*100, fnume*3

*-----------------------------------------------------------------------
      character gfnam*100
      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /mpi00/ npe, me

*-----------------------------------------------------------------------

      dimension   rm(nr+1)
      dimension   zm(nz+1)
      dimension   eb(ne+1)
      dimension   ew(ne)
      dimension   tr(np,ne,nr,nz,2)

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> np
      dimension tott(np,2),totnorm(np) ! totnorm is added on 2017/11/21 for normalization

      character hsunit(32)*30

      data hsunit(1) / 'T.L. [cm/event/source]'/
      data hsunit(2) / 'T.L. [cm/MeV/source]'/
      data hsunit(3) / 'T.L. [cm/(keV/um)/source]'/
      data hsunit(4) / 'T.L. [cm/Gy/source]'/
      data hsunit(5) / 'Dose [MeV/event/source]'/
      data hsunit(6) / 'Dose [MeV/MeV/source]'/
      data hsunit(7) / 'Dose [MeV/(keV/um)/source]'/
      data hsunit(8) / 'Dose [MeV/Gy/source]'/
      data hsunit(9) / 'T.L. [cm/ln(event)/source]'/
      data hsunit(10)/ 'T.L. [cm/ln(MeV)/source]'/
      data hsunit(11)/ 'T.L. [cm/ln(keV/um)/source]'/
      data hsunit(12)/ 'T.L. [cm/ln(Gy)/source]'/
      data hsunit(13)/ 'Dose [MeV/ln(event)/source]'/
      data hsunit(14)/ 'Dose [MeV/ln(MeV)/source]'/
      data hsunit(15)/ 'Dose [MeV/ln(keV/um)/source]'/
      data hsunit(16)/ 'Dose [MeV/ln(Gy)/source]'/
      data hsunit(17)/ 'T.L. [cm/source]'/
      data hsunit(18)/ 'T.L. [cm/source]'/
      data hsunit(19)/ 'T.L. [cm/source]'/
      data hsunit(20)/ 'T.L. [cm/source]'/
      data hsunit(21)/ 'Dose [MeV/source]'/
      data hsunit(22)/ 'Dose [MeV/source]'/
      data hsunit(23)/ 'Dose [MeV/source]'/
      data hsunit(24)/ 'Dose [MeV/source]'/
      data hsunit(25)/ 'n*f(n) [dimensionless]'/
      data hsunit(26)/ 'E*f(E) [dimensionless]'/
      data hsunit(27)/ 'y*f(y) [dimensionless]'/
      data hsunit(28)/ 'z*f(z) [dimensionless]'/
      data hsunit(29)/ 'n*d(n) [event]'/
      data hsunit(30)/ 'E*d(E) [MeV]'/
      data hsunit(31)/ 'y*d(y) [keV/um]'/
      data hsunit(32)/ 'z*d(z) [Gy]'/

      character hxunit(0:3)*12
      data hxunit(0) / 'n [Event]'/
      data hxunit(1) / 'e [MeV]'/
      data hxunit(2) / 'y [keV/um]'/
      data hxunit(3) / 'z [Gy]'/

      character cha*1
      data cha /"'"/

cfrtati 2021/10/05 chl, chm moved to partmod

      character dc2*4
cfrtati 2021/10/05 6 -> itmxpt
      character chp(itmxpt)*11  ! kitamura22/03/31
      character chq(itmxpt)*9   ! kitamura22/03/31


*-----------------------------------------------------------------------

      data pi/3.14159265d+0/

      character rpa*1
      data rpa /'}'/
      character yen*1

      include 'samepage_include/samepage000_norm.inc'


*-----------------------------------------------------------------------
*        set mesh volume ( unit = 1-3 ; vol = 1.0 )
*-----------------------------------------------------------------------

                 vl(ir,iz) = 1.0d0
                 vl_r = 1.0d0
                 vl_z = 1.0d0

      include 'samepage_include/samepage001.inc'

*-----------------------------------------------------------------------

      yen  = char(92)
      igsh = 0

*-----------------------------------------------------------------------
      np_mxang = np
      if ( itmxang(m).ne.0 .and. iabs(itmxang(m)).lt.np ) then
        np_mxang = iabs(itmxang(m))
      end if

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

               call wtpname(m,np,chp,chq)

*-----------------------------------------------------------------------
*        c1 : nomalization for source
*-----------------------------------------------------------------------

            if ( rsouin .gt. 0d0 ) then ! S.H. (2016.7.26)

               c1 = 1.0d+0 / rsouin

            else

               c1 = 0d0

            end if

*-----------------------------------------------------------------------
*           itunt(m) = 1 : cm/z/source
*                    = 2 : MeV/z/source
*                    = 3 : cm/ln(z)/source
*                    = 4 : MeV/ln(z)/source
*                    = 5 : cm/source
*                    = 6 : MeV/source
*                    = 7 : y*f(y)
*                    = 8 : y*d(y)
*           itsun(m) = 1 : MeV
*                    = 2 : keV/um
*                    = 3 : Gy
*-----------------------------------------------------------------------
            if( itunt(m) .le. 2 .or. itunt(m) .eq. 7) then ! T.Sato 2017/11/21

               do i = 1, ne

                  ew(i) = ( eb(i+1) - eb(i) )

               end do
               ew_sum = eb(ne+1) - eb(1)

            else if( itunt(m) .le. 4 .or. itunt(m) .eq. 8) then ! T.Sato 2017/11/21

               do i = 1, ne

                  ew(i) = log( eb(i+1) / eb(i) )

               end do
               ew_sum = log( eb(ne+1) / eb(1) )

            else

               do i = 1, ne

                  ew(i) = 1.d0

               end do
               ew_sum = 1.0d0

            end if

*-----------------------------------------------------------------------
*        relative error and  unit conversion
*-----------------------------------------------------------------------

                  cmax = 0.0
                  cmin = 1.e+33
                  isdz = 0
                  stdm = 0.0
                  itstd(m) = 1

            facmax(m) = 1.d0
            if( rtfac(m) .lt. 0.d0 ) then
               facmax(m) = 0.d0

               do 101 iz = 1, nz
               do 101 ir = 1, nr
               do 101 ie = 1, ne
               do 101 ip = 1, np

                  if( tr(ip,ie,ir,iz,1) .gt. 0.d0 ) then

                     fmaxfc = tr(ip,ie,ir,iz,1) / vl(ir,iz) / ew(ie)

                     if( facmax(m) .lt. fmaxfc) facmax(m) = fmaxfc

                  end if

  101          continue

            end if

            do 100 iz = 1, nz
            do 100 ir = 1, nr
            do 100 ie = 1, ne
            do 100 ip = 1, np

               if( tr(ip,ie,ir,iz,1) .gt. 0.d0 ) then

                  call calc_stdev(m,Xa,sigx,
     &                            tr(ip,ie,ir,iz,1),
     &                            tr(ip,ie,ir,iz,2),
     &             abs(rtfac(m)/facmax(m))/vl(ir,iz)/ew(ie))

                  tr(ip,ie,ir,iz,1) = Xa
                  tr(ip,ie,ir,iz,2) = sigx
                  if( sigx .gt. stdm ) stdm = sigx

                  if( tr(ip,ie,ir,iz,1) .gt. cmax )
     &                                   cmax = tr(ip,ie,ir,iz,1)

                  if( tr(ip,ie,ir,iz,1) .lt. cmin )
     &                                   cmin = tr(ip,ie,ir,iz,1)

               else

                  isdz = 1
                  tr(ip,ie,ir,iz,2) = 0.0

               end if

! sumover
               fact_in = abs(rtfac(m)/facmax(m))
               call psedrz_sumover_stdev(0,m,ip,ie,ir,iz,
     &                fact_in,ew(ie),vl(ir,iz),ew_sum,vl_r,vl_z)


  100       continue

            if( nobch .gt. ist_bat ) then
            if( rtstd(m) .gt. 0.d0 .and.
     &          stdm .gt. 0.d0 .and. isdz .eq. 0 .and.
     &          stdm .lt. rtstd(m) ) itstd(m) = 0
            end if

*-----------------------------------------------------------------------
*     out put unit = 31  : temporary number
*-----------------------------------------------------------------------

      do iax = 1, itfln(m)

!OBINATA(2012.9.7): output *.err
        noe = 1
        if ( any( itaxs(m,iax) .eq. (/ 7, 8, 9, 10 /) )
     &      .and. ittwo(m) .ne. 4 .and. icntl .ne. 8 )
     &    noe = 2

        do ioe = 1, noe

         if( itall .eq. 2 .and. nobch .lt. maxbch ) then

            write(fnume,'(i3.3)') nobch
!OBINATA(2012.9.7): output *.err
            if ( ioe .eq. 1 ) then
              fname = ctfln(m,iax)(1:itfll(m,iax))//'.'//fnume
            else
              call mk_2derrfn(ctfln(m,iax),fname,itfll(m,iax))
            end if

         else if ( itall.eq.4 ) then
            write(fnume,'(i3.3)') nobch
            if ( npe.gt.1 ) write (fnume,'(i3.3)') nobch/(npe-1)
            if ( ioe.eq.1 ) then
              call mk_2dnumfn(ctfln(m,iax),fname,itfll(m,iax),
     &             nobch,maxbch,npe)
            else
              call mk_2dnerfn(ctfln(m,iax),fname,itfll(m,iax),fnume)
            end if

         else

!OBINATA(2012.9.7): output *.err
            if ( ioe .eq. 1 ) then
              fname = ctfln(m,iax)
            else
              call mk_2derrfn(ctfln(m,iax),fname,itfll(m,iax))
            end if

         end if

            iot = 31
            open(iot, file = fname, status = 'unknown' )

*-----------------------------------------------------------------------
            gfnam = ctfln(m,iax)
            igfmn = itfll(m,iax)
            igser = itger(m)

*-----------------------------------------------------------------------
*     input echo
*-----------------------------------------------------------------------

               call sedech(iot,m,iax,1)

      include 'samepage_include/samepage002_perz_norm.inc'
      include 'samepage_include/samepagechp_perz_norm.inc'
      include 'samepage_include/samepageseti.inc'

*-----------------------------------------------------------------------
*        SED axis
*-----------------------------------------------------------------------

         if( itaxs(m,iax) .eq. 1 ) then

               inum = 0

            do iri = 1, nr, nrstepi
            do izi = 1, nz, nzstepi
            do ipi = 1, np, npstepi
               ir = iri
               iz = izi
               ip = ipi

               inum = inum + 1

                  write(iot,'(/"#",78("-"))')

               if( inum .eq. 1 ) then
                  write(iot,'( "#newpage:")')
               else
                  write(iot,'( " newpage:")')
               end if

               if( rtfac(m) .lt. 0.d0 )
     &           write(iot,
     &           '( "#restart maximum for normalization:",1p1e14.7)')
     &           facmax(m)

