*        y axis
*-----------------------------------------------------------------------

         else if( itaxs(m,iax) .eq. 4 ) then

               inum = 0

            do iei = 1, ne, nestepi
            do ixi = 1, nx, nxstepi
            do izi = 1, nz, nzstepi
            do ipi = 1, np, npstepi
               ie = iei
               ix = ixi
               iz = izi
