         end if

  900    continue

*-----------------------------------------------------------------------
         deallocate( ixyz )
cnais 2023/01/31
      include 'samepage_include/samepage999_norm.inc'


      return
      end


************************************************************************
*                                                                      *
      subroutine getfitele(CD,EE)
*                                                                      *
*       Get fitting parameter for electron and muon                    *
*       last modified by T.Sato on 2005/10/20                          *
*                                                                      *
*       CD : Cell Diameter in um                                       *
*       EE : Electron Energy in MeV                                    *
*                                                                      *
************************************************************************

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'zdist.inc'

*-----------------------------------------------------------------------

	dimension A(2) ! temporary use parameter

      do ic=2,mcsizeele-1

         if(Csizeele(ic).ge.CD) go to 10

      enddo

   10 ic1=ic-1

      do ie=2,neele-1

         if(Efitele(ie).ge.EE) go to 30

      end do

   30 ie1=ie-1

*-----------------------------------------------------------------------
*     Get Acurr Parameters
*-----------------------------------------------------------------------

      do i=1,mpara

         idx=0

         do ic=ic1,ic1+1

            idx=idx+1

            if(EE.ge.Efitele(neele)) then

               A(idx)=Afitele(ic,neele,i)

            elseif(EE.le.Efitele(1)) then

               A(idx)=Afitele(ic,1,i)

            else

               Alow=Afitele(ic,ie1,i)

               Ahig=Afitele(ic,ie1+1,i)

               Ratio=(log10(EE)-log10(Efitele(ie1)))
     1           /(log10(Efitele(ie1+1))-log10(Efitele(ie1)))

               A(idx)=Alow+(Ahig-Alow)*Ratio

            endif

         enddo

         Ratio=(log10(CD)-log10(Csizeele(ic1)))
     1        /(log10(Csizeele(ic1+1))-log10(Csizeele(ic1)))

         if(Ratio.gt.1.0) Ratio=1.0

         Acurr(i)=A(1)+(A(2)-A(1))*Ratio

      end do

*-----------------------------------------------------------------------
*     Get Pcurr Parameters
*-----------------------------------------------------------------------

      do i=1,npeak

         idx=0

         do ic=ic1,ic1+1

            idx=idx+1

            if(EE.ge.Efitele(neele)) then

               A(idx)=Pfitele(ic,neele,i)

            elseif(EE.le.Efitele(1)) then

               A(idx)=Pfitele(ic,1,i)

            else

               Alow=Pfitele(ic,ie1,i)

               Ahig=Pfitele(ic,ie1+1,i)

               Ratio=(log10(EE)-log10(Efitele(ie1)))
     1           /(log10(Efitele(ie1+1))-log10(Efitele(ie1)))

               A(idx)=Alow+(Ahig-Alow)*Ratio

            endif

         end do

         Ratio=(log10(CD)-log10(Csizeele(ic1)))
     1     /(log10(Csizeele(ic1+1))-log10(Csizeele(ic1)))

         if(Ratio.gt.1.0) Ratio=1.0

         Pcurr(i)=A(1)+(A(2)-A(1))*Ratio

         if(Pcurr(i).le.0.0) Pcurr(i)=0.0

      end do

*-----------------------------------------------------------------------
*     Get Ccurr(1)
*-----------------------------------------------------------------------

      Ccurr(1)=10.0*CD*1.0e-4  ! dE/dx (MeV/cm) * Cell diameter (cm)

*-----------------------------------------------------------------------

      return

      end

************************************************************************
*                                                                      *
      subroutine getfit(CD,iz,EE,dEdx)
*                                                                      *
*       Get fitting parameter for nucleon                              *
*       last modified by T.Sato on 2009/02/12                          *
*                                                                      *
*       CD : Cell Diameter in um                                       *
*       iZ : Z number of particle                                      *
*       EE : Kinetic Energy in MeV/n                                   *
*       dEdx : dE/dx in MeV/cm                                         *
*                                                                      *
************************************************************************

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'zdist.inc'

*-----------------------------------------------------------------------

      dimension A(6)

*-----------------------------------------------------------------------
*     Find Cell Diameter, Z number & Energy Bin
*-----------------------------------------------------------------------

      do ic=2,mcsize-1

         if(Csize(ic).ge.CD) go to 10

      enddo

   10 ic1=ic-1

      do ip=2,npart-1

         if(iZfit(ip).ge.iZ) go to 20

      end do

   20 ip1=ip-1

      do ie=2,neinc-1

         if(Efit(ie).ge.EE) go to 30

      end do

   30 ie1=ie-1

*-----------------------------------------------------------------------
*     Get Acurr Parameters except for Acurr(1)
*-----------------------------------------------------------------------

      do i=2,mpara

         idx=0

         do ic=ic1,ic1+1

            do ip=ip1,ip1+1

               idx=idx+1

               Alow=Afit(ic,ip,ie1,i)

               Ahig=Afit(ic,ip,ie1+1,i)

               if(i.eq.2.and.Alow.lt.1.0e-5) Alow=Ahig ! for neglecting 1st term, use another value

               if(i.eq.2.and.Ahig.lt.1.0e-5) Ahig=Alow ! for neglecting 1st term, use another value


               Ratio=(log10(EE)-log10(Efit(ie1)))
     1           /(log10(Efit(ie1+1))-log10(Efit(ie1)))

               if(Ratio.lt.0.0) Ratio=0.0

               if(Ratio.gt.1.0) Ratio=1.0

               A(idx)=Alow+(Ahig-Alow)*Ratio

            end do

         enddo

         if(i.eq.2.and.A(1).lt.1.0e-5) A(1)=A(2) ! for neglecting 1st term, use another value

         if(i.eq.2.and.A(2).lt.1.0e-5) A(2)=A(1) ! for neglecting 1st term, use another value

         if(i.eq.2.and.A(3).lt.1.0e-5) A(3)=A(4) ! for neglecting 1st term, use another value

         if(i.eq.2.and.A(4).lt.1.0e-5) A(4)=A(3) ! for neglecting 1st term, use another value


         Ratio=(log10(iZ*1.0)-log10(iZfit(ip1)*1.0))
     1        /(log10(iZfit(ip1+1)*1.0)-log10(iZfit(ip1)*1.0))

         if(Ratio.lt.0.0) Ratio=0.0

         if(Ratio.gt.1.0) Ratio=1.0

         A(5)=A(1)+(A(2)-A(1))*Ratio

         A(6)=A(3)+(A(4)-A(3))*Ratio

         if(i.eq.2.and.A(5).lt.1.0e-5) A(5)=A(6) ! for neglecting 1st term, use another value

         if(i.eq.2.and.A(6).lt.1.0e-5) A(6)=A(5) ! for neglecting 1st term, use another value

         Ratio=(log10(CD)-log10(Csize(ic1)))
     1        /(log10(Csize(ic1+1))-log10(Csize(ic1)))

         if(i.ne.3.and.Ratio.gt.1.0) Ratio=1.0

         Acurr(i)=A(5)+(A(6)-A(5))*Ratio

         if(i.eq.3.and.Acurr(i).gt.1.0) Acurr(1)=1.0

      end do

*-----------------------------------------------------------------------
*     Get Pcurr Parameters
*-----------------------------------------------------------------------

      do i=1,npeak

         idx=0

         do ic=ic1,ic1+1

            do ip=ip1,ip1+1

               idx=idx+1

               Alow=Pfit(ic,ip,ie1,i)

               Ahig=Pfit(ic,ip,ie1+1,i)


               Ratio=(log10(EE)-log10(Efit(ie1)))
     1           /(log10(Efit(ie1+1))-log10(Efit(ie1)))

               if(Ratio.lt.0.0) Ratio=0.0

               if(Ratio.gt.1.0) Ratio=1.0

               A(idx)=Alow+(Ahig-Alow)*Ratio

            end do

         end do


         Ratio=(log10(iZ*1.0)-log10(iZfit(ip1)*1.0))
     1        /(log10(iZfit(ip1+1)*1.0)-log10(iZfit(ip1)*1.0))

         if(Ratio.lt.0.0) Ratio=0.0

         if(Ratio.gt.1.0) Ratio=1.0

         A(5)=A(1)+(A(2)-A(1))*Ratio

         A(6)=A(3)+(A(4)-A(3))*Ratio

         Ratio=(log10(CD)-log10(Csize(ic1)))
     1     /(log10(Csize(ic1+1))-log10(Csize(ic1)))

         if(Ratio.gt.1.0) Ratio=1.0

         Pcurr(i)=A(5)+(A(6)-A(5))*Ratio

      end do

*-----------------------------------------------------------------------
*     Get Ccurr(1) & update Acurr(1)
*-----------------------------------------------------------------------

      Ccurr(1)=dEdx*CD*1.0e-4  ! dE/dx (MeV/cm) * Cell diameter (cm)

      Acurr(1)=geta1(Ccurr(1),Acurr(2),Acurr(3))

*-----------------------------------------------------------------------

      return
      end

************************************************************************
*                                                                      *
      function geta1(c,a2,a3)
*                                                                      *
*       Update Acurr(1) based on Ccurr(1), Acurr(2) & Acurr(3)         *
*       last modified by T.Sato on 2005/10/20                          *
*                                                                      *
************************************************************************

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      data ndiv /20/

      dx=c*a3/ndiv
      if(dx.lt.1.0e-5) dx = 1.0e-5

      sum=0.0

      x=dx*0.5 ! initial x

      do i=1,10000

         tmp1=a2*(x-c*a3)
         tmp1 = min(tmp1,100.0)

         tmp=x**2/(exp(tmp1)+1)*dx

         sum=sum+tmp

         if(x.gt.c*a3.and.tmp/sum.lt.1.0e-5) go to 10

         x=x+dx

      end do

   10 geta1=a3/sum

      return

      end

************************************************************************
*                                                                      *
      function zdistfunc(x)
*                                                                      *
*       Read Input Parameters for Z-distribution                       *
*       last modified by T.Sato on 2005/10/20                          *
*                                                                      *
*       x : z in MeV                                                   *
*                                                                      *
************************************************************************

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'zdist.inc'

*-----------------------------------------------------------------------
*     Define constant parameter
*-----------------------------------------------------------------------

      Ccurr(2)=1.0/10.9e-6 ! Constant Parameter

*-----------------------------------------------------------------------

      if(Acurr(1).lt.0.0) then  ! for high-energy electron

         first=Acurr(2)*x*Ccurr(2)/(Acurr(3)-1.0)
     &   *((Acurr(3)-1)/Acurr(3))**(x*Ccurr(2)) ! high-z part

      elseif(Acurr(1).gt.0.0.and.Acurr(3).gt.0.0505) then  ! for ion with core

         tmp = Acurr(2)*(x-Ccurr(1)*Acurr(3))
         tmp = min(tmp,100.0)    ! avoid overflow

         first=Acurr(1)*x**2/(exp(tmp)+1)  ! core part

      else

         first=0.0

      endif

      if(Acurr(5).gt.1.01) then

         second=Acurr(4)*x*Ccurr(2)/(Acurr(5)-1.0)*
     &   ((Acurr(5)-1)/Acurr(5))**(x*Ccurr(2)) ! low-energy delta part

      else

         second=0.0

      endif

      if(Acurr(7).gt.1.01) then

         third=Acurr(6)*x*Ccurr(2)/(Acurr(7)-1.0)*
     &   ((Acurr(7)-1)/Acurr(7))**(x*Ccurr(2)) ! high-energy delta part

      else

        third=0.0

      endif

      zdistfunc=first+second+third

      if (zdistfunc.lt.1.0e-5) zdistfunc = 0.0

      return

      end


************************************************************************
*                                                                      *
      subroutine readZdist
*                                                                      *
*       Read Input Parameters for Z-distribution                       *
*       last modified by K.Niita on 2006/02/10                         *
*       written by T.Sato on 2005/10/20                                *
*                                                                      *
************************************************************************

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      include 'zdist.inc'

*-----------------------------------------------------------------------

      character chatmp25*25,chatmp26*26

*-----------------------------------------------------------------------







*-----------------------------------------------------------------------
*     Define constant parameter
*-----------------------------------------------------------------------

      Ccurr(2)=1.0/10.9e-6 ! Constant Parameter

*-----------------------------------------------------------------------
*     Read Input Parameters for Nucleus
*-----------------------------------------------------------------------

      open(unit=321,file='zdist.inp',status='old')
      open(unit=322,file='zdist.dat',status='unknown')

      do ic=1,mcsize


        do ip=1,npart


          do ie=1,neinc


            read(321,'(a26,40e12.5)')  chatmp26,
     &      (Afit(ic,ip,ie,i),i=1,mpara),
     &      (Pfit(ic,ip,ie,i),i=1,npeak)


          enddo

             write(322,'(6x,"data ((Afit(",i1,",",i1,
     &                      ",ie,i),i=1,mpara),",
     &       "(Pfit(",i1,",",i1,",ie,i),i=1,npeak),"/
     &       5x,"&      ie=1,neinc) /")')
     &       ic,ip,ic,ip

             write(322,'(100(5x,"& ",5(1p1e11.4,",")/))')
     &      ((Afit(ic,ip,ie,i),i=1,mpara),
     &      (Pfit(ic,ip,ie,i),i=1,npeak),ie=1,neinc)


        enddo

      enddo

*-----------------------------------------------------------------------
*     Read Input Parameters for Electron
*-----------------------------------------------------------------------

      do ic=1,mcsize


        read(321,'(a25,40e12.5)') chatmp25,
     &  ((AfitEle(ic,ie,i),i=1,mpara),ie=1,neele),
     &  ((PfitEle(ic,ie,i),i=1,npeak),ie=1,neele)

      enddo



      close(unit=321)
      close(unit=322)

      end

