************************************************************************
*                                                                      *
      function Gau(x,sigma)
*                                                                      *
*       Gaussian Distribution used in Auger peak width calculation     *
*                                                                      *
************************************************************************

*-----------------------------------------------------------------------

      implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

      Gau = exp(-x**2/(2.0*sigma**2))

      end


************************************************************************
      subroutine getemm(amin,amax,aint,percentile,nmax,adim)
*     find persubroutine for finding certain minimum value             *
*     T.Sato 2024/05/27                                                *
************************************************************************
      implicit double precision (a-h,o-z)

      dimension adim(nmax)

      do i=1,nmax
       amax=-1.0e10
       do ii=i,nmax
        if(adim(ii).gt.amax) then
         amax=adim(ii)
         iimax=ii
        endif
       enddo
       adim(iimax)=adim(i)
       adim(i)=amax
      enddo

      aint=0.0
      do i=1,nmax
       if(adim(i).eq.0.0) exit
       aint=aint+adim(i)
      enddo
      inz=i-1 ! number of non-zero data

      ipercentile=max(1,nint(inz*percentile))

      amin=adim(ipercentile)
      amax=adim(1)+amin ! maximum value + pedestal

      return
      end

************************************************************************
*                                                                      *
*  sumover subroutine                                                  *
*                                                                      *
************************************************************************



************************************************************************
*                                                                      *
      subroutine tsedreg_sumover(m,maxcas,
     &                   np,  ne, nr,tr0x)
*     tr_sum(np,ne,nr,2)                                               *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nr)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tsedreg_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne, nr, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      itrgn_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine tsedreg_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne, nr, tr0,
     &           np_sum,  ne_sum, nr_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nr)
      dimension   tr_sum(np_sum,ne_sum,nr_sum,2)

      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do ir = 1,nr
        do ip = 1,np

          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,ir) / maxcas
          end do
          tr_sum(ip,1,ir,1) =
     &           tr_sum(ip,1,ir,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,ir,2) = tr_sum(ip,1,ir,2) + 1.0d0
           else
            tr_sum(ip,1,ir,2) =
     &           tr_sum(ip,1,ir,2) + tr0_sum ** 2
          endif
        end do
        end do
!

      elseif(itaxs_in == 2) then    ! r
        do ie = 1,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do ir = 1,nr
            tr0_sum = tr0_sum + tr0(ip,ie,ir) / maxcas
          end do
          tr_sum(ip,ie,1,1) =
     &           tr_sum(ip,ie,1,1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,1,2) = tr_sum(ip,ie,1,2) + 1.0d0
          else
            tr_sum(ip,ie,1,2) =
     &           tr_sum(ip,ie,1,2) + tr0_sum ** 2
          endif
        end do
        end do

       end if
       return
       end


************************************************************************
*                                                                      *
