          call psedrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,nzstepi,
     &    ipi,iei,iri,izi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itrnm_sum(m,iax),
     &    itznm_sum(m,iax),tr_sum)


      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * nrstepi * nzstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

          call psedrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,nzstepi,
     &    ipi,iei,iri,izi,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itrnm_sum(m,iax),
     &    itznm_sum(m,iax),tr_sum)

          deallocate (tott_in)

      endif

      return
      end

************************************************************************
*                                                                      *
      subroutine psedrz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nrstepi,nzstepi,
     &    ipi,iei,iri,izi,maxtott,tott_sum,
     &    np_sum,ne_sum,nr_sum,nz_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nr_sum,nz_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
          do izloop=1,nzstepi
            do irloop=1,nrstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,iri+irloop-1,
     &                izi+izloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,iri+irloop-1,
     &                izi+izloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do

      return
      end

************************************************************************
*                                                                      *
      subroutine tsedxyz_sumover(m,maxcas,
     &                   np,  ne, nx, ny, nz, tr0x)
*     tr_sum(np,ne,nx*ny*nz,2)                                               *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nx*ny*nz)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        if(n_tr_sum > 0) then

          call tsedxyz_sumover_sub(maxcas,itaxs(m,iax),
     &      np,  ne, nx, ny, nz, tr0x,
     &      itpan_sum(m,iax),itenm_sum(m,iax),
     &      itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &      tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine tsedxyz_sumover_sub(maxcas_in,itaxs_in,
     &           np,  ne, nx, ny, nz, tr0,
     &           np_sum,  ne_sum, nx_sum, ny_sum, nz_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nx*ny*nz)
      dimension   tr_sum(np_sum,ne_sum,nx_sum*ny_sum*nz_sum,2)

      icf(ix,iy,iz) = ix + ( iy - 1 ) * nx + ( iz - 1 ) * nx * ny
      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                   + ( iz - 1 ) * nx_sum * ny_sum


      maxcas = maxcas_in
      if(maxcas_in == 0) then
         maxcas = 1
      endif

      if(itaxs_in == 1) then  ! energ
        do iz = 1,nz
        do iy = 1,ny
        do ix = 1,nx
        do ip = 1,np

          tr0_sum = 0.0d0
          do ie = 1,ne
            tr0_sum = tr0_sum + tr0(ip,ie,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,1,icf_sum(ix,iy,iz),1) =
     &           tr_sum(ip,1,icf_sum(ix,iy,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,1,icf_sum(ix,iy,iz),2) =
     %             tr_sum(ip,1,icf_sum(ix,iy,iz),2) + 1.0d0
           else
            tr_sum(ip,1,icf_sum(ix,iy,iz),2) =
     &           tr_sum(ip,1,icf_sum(ix,iy,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do
!
      else if(itaxs_in == 3) then  ! x
        do iz = 1,nz
        do iy = 1,ny
        do ie = 1,ne
        do ip = 1,np

          tr0_sum = 0.0d0
          do ix = 1,nx
            tr0_sum = tr0_sum + tr0(ip,ie,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,icf_sum(1,iy,iz),1) =
     &           tr_sum(ip,ie,icf_sum(1,iy,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,icf_sum(1,iy,iz),2) =
     %             tr_sum(ip,ie,icf_sum(1,iy,iz),2) + 1.0d0
           else
            tr_sum(ip,ie,icf_sum(1,iy,iz),2) =
     &           tr_sum(ip,ie,icf_sum(1,iy,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do

      else if(itaxs_in == 4) then  ! y
        do iz = 1,nz
        do ix = 1,nx
        do ie = 1,ne
        do ip = 1,np

          tr0_sum = 0.0d0
          do iy = 1,ny
            tr0_sum = tr0_sum + tr0(ip,ie,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,icf_sum(ix,1,iz),1) =
     &           tr_sum(ip,ie,icf_sum(ix,1,iz),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,icf_sum(ix,1,iz),2) =
     %             tr_sum(ip,ie,icf_sum(ix,1,iz),2) + 1.0d0
           else
            tr_sum(ip,ie,icf_sum(ix,1,iz),2) =
     &           tr_sum(ip,ie,icf_sum(ix,1,iz),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do

      else if(itaxs_in == 5) then  ! z
        do iy = 1,ny
        do ix = 1,nx
        do ie = 1,ne
        do ip = 1,np
          tr0_sum = 0.0d0
          do iz = 1,nz
            tr0_sum = tr0_sum + tr0(ip,ie,icf(ix,iy,iz)) / maxcas
          end do
          tr_sum(ip,ie,icf_sum(ix,iy,1),1) =
     &           tr_sum(ip,ie,icf_sum(ix,iy,1),1) + tr0_sum
          if(maxcas_in == 0) then
            tr_sum(ip,ie,icf_sum(ix,iy,1),2) =
     %             tr_sum(ip,ie,icf_sum(ix,iy,1),2) + 1.0d0
           else
            tr_sum(ip,ie,icf_sum(ix,iy,1),2) =
     &           tr_sum(ip,ie,icf_sum(ix,iy,1),2) + tr0_sum ** 2
          endif
        end do
        end do
        end do
        end do


       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine psedxyz_sumover_stdev(mode,m,ip,ie,ix,iy,iz,
     &                fact_in,ew,vl,ew_sum,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

       else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/ew
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 3 .and. ix == 1) then
             sum_fact = sum_fact * vl / vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
             sum_fact = sum_fact * vl / vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call psedxyz_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,ix,iy,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itxnm_sum(m,iax),
     &         itynm_sum(m,iax),itznm_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine psedxyz_sumover_stdev_ntf(mode,m,ntf,ip,ie,ix,iy,iz,
     &                fact_in,ew,vl,ew_sum,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if

       else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)
       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/vl/ew
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 3 .and. ix == 1) then
             sum_fact = sum_fact * vl / vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
             sum_fact = sum_fact * vl / vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl / vl_z
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call psedxyz_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,ix,iy,iz,
     &         itpan_sum(m,iax),itenm_sum(m,iax),itxnm_sum(m,iax),
     &         itynm_sum(m,iax),itznm_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine psedxyz_sumover_stdev_sub(mode,m,sum_fact,
     &                   ip,ie,ix,iy,iz,
     &                   np_sum,ne_sum,nx_sum,ny_sum,nz_sum,
     &                   tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension tr_sum(np_sum,ne_sum,nx_sum*ny_sum*nz_sum,2)

      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                   + ( iz - 1 ) * nx_sum * ny_sum

      if(tr_sum(ip,ie,icf_sum(ix,iy,iz),1) > 0.0) then
         if(mode == 0) Then
                  call calc_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,icf_sum(ix,iy,iz),1),
     &                            tr_sum(ip,ie,icf_sum(ix,iy,iz),2),
     &                            sum_fact)
         else
                  sum_fact_r = 1.0d0 / sum_fact
                  call invert_stdev(m,Xa,sigx,
     &                            tr_sum(ip,ie,icf_sum(ix,iy,iz),1),
     &                            tr_sum(ip,ie,icf_sum(ix,iy,iz),2),
     &                            sum_fact_r)
         endif

                  tr_sum(ip,ie,icf_sum(ix,iy,iz),1) = Xa
                  tr_sum(ip,ie,icf_sum(ix,iy,iz),2) = sigx

      else

        tr_sum(ip,ie,icf_sum(ix,iy,iz),2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  psedxyz_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,ixi,iyi,izi,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)
      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

      call psedxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,ixi,iyi,izi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itxnm_sum(m,iax),
     &    itynm_sum(m,iax),itznm_sum(m,iax),tr_sum)

      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * nxstepi * nystepi * nzstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

      call psedxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,ixi,iyi,izi,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),itxnm_sum(m,iax),
     &    itynm_sum(m,iax),itznm_sum(m,iax),tr_sum)

          deallocate (tott_in)

      endif

      return
      end

************************************************************************
*                                                                      *
      subroutine psedxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,nxstepi,nystepi,nzstepi,
     &    ipi,iei,ixi,iyi,izi,maxtott,tott_sum,
     &    np_sum,ne_sum,nx_sum,ny_sum,nz_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nx_sum*ny_sum*nz_sum,2)

      real(8) :: tott_sum(maxtott,2)

      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                   + ( iz - 1 ) * nx_sum * ny_sum

        i = 0
        do izloop=1,nzstepi
          do iyloop=1,nystepi
            do ixloop=1,nxstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,
     &                icf_sum(ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1),k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,
     &                icf_sum(ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1),k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
          end do
        end do

      return
      end


************************************************************************
*                                                                      *
      subroutine twwgreg_sumover(m,maxcas,
     &                   np,  ne, nt, nr, nm, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nr,nm,2)                                         *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nr,nm,*)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call twwgreg_sumover_sub(maxcas,itaxs(m,iax),
     &     np,  ne, nt, nr, nm,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itrgn_sum(m,iax),
     &     itmst_sum(m,iax),tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine twwgreg_sumover_sub(maxcas,itaxs_in,
     &           np,  ne, nt, nr, nm, tr0,
     &           np_sum,  ne_sum, nt_sum, nr_sum,
     &           nm_sum, tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nr,nm,*)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,
     &                   nm_sum,2)

      if(itaxs_in == 1) then  ! energ
        do im = 1, nm
        do ir = 1, nr
        do it = 1, nt
        do ip = 1, np
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,im,1)
     &              / maxcas
          end do
          tr_sum(ip,1,it,ir,im,1) =
     &           tr_sum(ip,1,it,ir,im,1) + tr0_sum
          tr_sum(ip,1,it,ir,im,2) =
     &          tr_sum(ip,1,it,ir,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
!

      elseif(itaxs_in == 2) then    ! r
        do im = 1, nm
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do ir = 1, nr
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,im,1)
     &              / maxcas
          end do
          tr_sum(ip,ie,it,1,im,1) =
     &           tr_sum(ip,ie,it,1,im,1) + tr0_sum
          tr_sum(ip,ie,it,1,im,2) =
     &           tr_sum(ip,ie,it,1,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do im = 1, nm
        do ir = 1, nr
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do it = 1, nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,im,1)
     &              / maxcas
          end do
          tr_sum(ip,ie,1,ir,im,1) =
     &           tr_sum(ip,ie,1,ir,im,1) + tr0_sum
          tr_sum(ip,ie,1,ir,im,2) =
     &          tr_sum(ip,ie,1,ir,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine pwwgreg_sumover_stdev(mode,m,ip,ie,it,ir,im,
     &                fact_in,ew,tw,vl,ew_sum,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

       else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/ew/tw/vl
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_sum
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pwwgreg_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,it,ir,im,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrgn_sum(m,iax),
     &         itmst_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pwwgreg_sumover_stdev_ntf(mode,m,ntf,ip,ie,it,ir,im,
     &                fact_in,ew,tw,vl,ew_sum,tw_sum,vl_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

       if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if

       else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)

       endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/ew/tw/vl
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. ir == 1) then
             sum_fact = sum_fact * vl / vl_sum
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pwwgreg_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,it,ir,im,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itrgn_sum(m,iax),
     &         itmst_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pwwgreg_sumover_stdev_sub(mode,m,sum_fact,
     &                   ip,ie,it,ir,im,
     &                   np_sum,ne_sum,nt_sum,nr_sum,
     &                   nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,
     &                   nm_sum,2)


      if(tr_sum(ip,ie,it,ir,im,1) > 0.0) then
        if(mode == 0) then
          call calc_stdev(m,Xa,sigx,
     &                  tr_sum(ip,ie,it,ir,im,1),
     &                  tr_sum(ip,ie,it,ir,im,2),
     &                  sum_fact)
        else
          sum_fact_r = 1.0d0 / sum_fact
          call invert_stdev(m,Xa,sigx,
     &                  tr_sum(ip,ie,it,ir,im,1),
     &                  tr_sum(ip,ie,it,ir,im,2),
     &                  sum_fact_r)
        endif

        tr_sum(ip,ie,it,ir,im,1) = Xa
        tr_sum(ip,ie,it,ir,im,2) = sigx

      else

        tr_sum(ip,ie,it,ir,im,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pwwgreg_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,ntstepi,nrstepi,nmstepi,
     &    ipi,iei,iti,iri,imi,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)
      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

          call pwwgreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nmstepi,
     &    ipi,iei,iti,iri,imi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itrgn_sum(m,iax),
     &    itmst_sum(m,iax),
     &    tr_sum)

      else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * ntstepi * nrstepi * nmstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

          call pwwgreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nmstepi,
     &    ipi,iei,iti,iri,imi,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itrgn_sum(m,iax),
     &    itmst_sum(m,iax),
     &    tr_sum)

          deallocate (tott_in)

      endif

      return
      end

************************************************************************
*                                                                      *
      subroutine pwwgreg_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nrstepi,nmstepi,
     &    ipi,iei,iti,iri,imi,maxtott,tott_sum,
     &    np_sum,ne_sum,nt_sum,nr_sum,nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nt_sum,nr_sum,nm_sum,2)

      real(8) :: tott_sum(maxtott,2)

        i = 0
        do imloop=1,nmstepi
          do irloop=1,nrstepi
            do itloop=1,ntstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                    if(mode == 0) then
                      tott_sum(i,k) =
     &                tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &                iri+riloop-1,imi+imloop-1,k)
                    else
                      tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &                iri+riloop-1,imi+imloop-1,k)
     &                = tott_sum(i,k)
                    endif
                  enddo
                end do
              end do
            end do
         end do
       end do

      return
      end

************************************************************************
*                                                                      *
      subroutine twwgxyz_sumover(m,maxcas,
     &                   np,  ne, nt,  nx, ny, nz, nm, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nx*ny*nz,nm,2)                                   *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nx*ny*nz,nm,*)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call twwgxyz_sumover_sub(maxcas,itaxs(m,iax),
     &     np,  ne, nt, nx, ny, nz, nm,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &     itmst_sum(m,iax),tr_sum)

        endif

      enddo

      return
      end


************************************************************************
*                                                                      *
      subroutine twwgxyz_sumover_sub(maxcas,itaxs_in,
     &           np,  ne, nt, nx, ny, nz, nm, tr0,
     &           np_sum,  ne_sum, nt_sum, nx_sum, ny_sum, nz_sum,
     &           nm_sum, tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nx*ny*nz,nm,*)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nx_sum*ny_sum*nz_sum,
     &                   nm_sum,2)

      icf(ix,iy,iz) = ix + ( iy - 1 ) * nx + ( iz - 1 ) * nx * ny
      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                  + ( iz - 1 ) * nx_sum * ny_sum

      if(itaxs_in == 1) then  ! energ
        do im = 1, nm
        do iz = 1, nz
        do iy = 1, ny
        do ix = 1, nx
        do it = 1, nt
        do ip = 1, np
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im,1)
     &              / maxcas
          end do
          tr_sum(ip,1,it,icf_sum(ix,iy,iz),im,1) =
     &           tr_sum(ip,1,it,icf_sum(ix,iy,iz),im,1) + tr0_sum
          tr_sum(ip,1,it,icf_sum(ix,iy,iz),im,2) =
     &          tr_sum(ip,1,it,icf_sum(ix,iy,iz),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do
!
      elseif(itaxs_in == 3) then    ! x
        do im = 1, nm
        do iz = 1, nz
        do iy = 1, ny
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do ix = 1, nx
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im,1)
     &              / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(1,iy,iz),im,1) =
     &           tr_sum(ip,ie,it,icf_sum(1,iy,iz),im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(1,iy,iz),im,2) =
     &           tr_sum(ip,ie,it,icf_sum(1,iy,iz),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 4) then    ! y
        do im = 1, nm
        do iz = 1, nz
        do ix = 1, nx
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do iy = 1, ny
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im,1)
     &              / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(ix,1,iz),im,1) =
     &           tr_sum(ip,ie,it,icf_sum(ix,1,iz),im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(ix,1,iz),im,2) =
     &           tr_sum(ip,ie,it,icf_sum(ix,1,iz),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 5) then    ! z
        do im = 1, nm
        do iy = 1, ny
        do ix = 1, nx
        do it = 1, nt
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do iz = 1, nz
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im,1)
     &              / maxcas
          end do
          tr_sum(ip,ie,it,icf_sum(ix,iy,1),im,1) =
     &           tr_sum(ip,ie,it,icf_sum(ix,iy,1),im,1) + tr0_sum
          tr_sum(ip,ie,it,icf_sum(ix,iy,1),im,2) =
     &           tr_sum(ip,ie,it,icf_sum(ix,iy,1),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

      elseif(itaxs_in == 11) then   ! time
        do im = 1, nm
        do iz = 1, nz
        do iy = 1, ny
        do ix = 1, nx
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do it = 1, nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,icf(ix,iy,iz),im,1)
     &              / maxcas
          end do
          tr_sum(ip,ie,1,icf_sum(ix,iy,iz),im,1) =
     &           tr_sum(ip,ie,1,icf_sum(ix,iy,iz),im,1) + tr0_sum
          tr_sum(ip,ie,1,icf_sum(ix,iy,iz),im,2) =
     &          tr_sum(ip,ie,1,icf_sum(ix,iy,iz),im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
        end do
        end do

       end if
       return
       end

************************************************************************
*                                                                      *
      subroutine pwwgxyz_sumover_stdev(mode,m,ip,ie,it,ix,iy,iz,im,
     &                fact_in,ew,tw,vl,ew_sum,tw_sum,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
        else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
        endif

        if(n_tr_sum > 0) then
             sum_fact = fact_in/ew/tw/vl
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 3 .and. ix == 1) then
             sum_fact = sum_fact * vl /vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
             sum_fact = sum_fact * vl /vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl /vl_z
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pwwgxyz_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,it,ix,iy,iz,im,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &         itmst_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pwwgxyz_sumover_stdev_ntf(mode,m,ntf,
     &                ip,ie,it,ix,iy,iz,im,
     &                fact_in,ew,tw,vl,ew_sum,tw_sum,vl_x,vl_y,vl_z)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM_NTF(tr_sum,m,ntf,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM_NTF(tr_sum,m,ntf,iax)
C for nonshared_tally option
!$       end if
        else
          ntfbase = mtalsize_sum(m) * (ntf-1)
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax)+ntfbase:)
        endif

        if(n_tr_sum > 0) then
             sum_fact = fact_in/ew/tw/vl
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 3 .and. ix == 1) then
             sum_fact = sum_fact * vl /vl_x
          else if(itaxs(m,iax) == 4 .and. iy == 1) then
             sum_fact = sum_fact * vl /vl_y
          else if(itaxs(m,iax) == 5 .and. iz == 1) then
             sum_fact = sum_fact * vl /vl_z
          else if(itaxs(m,iax) == 11 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call pwwgxyz_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,it,ix,iy,iz,im,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &         itmst_sum(m,iax),tr_sum)
          endif

        endif
      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine pwwgxyz_sumover_stdev_sub(mode,m,sum_fact,
     &                   ip,ie,it,ix,iy,iz,im,
     &                   np_sum,ne_sum,nt_sum,nx_sum,ny_sum,nz_sum,
     &                   nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      dimension   tr_sum(np_sum,ne_sum,nt_sum,nx_sum*ny_sum*nz_sum,
     &                   nm_sum,2)

      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                  + ( iz - 1 ) * nx_sum * ny_sum


      if(tr_sum(ip,ie,it,icf_sum(ix,iy,iz),im,1) > 0.0) then
        if(mode == 0) then
          call calc_stdev(m,Xa,sigx,
     &                  tr_sum(ip,ie,it,icf_sum(ix,iy,iz),im,1),
     &                  tr_sum(ip,ie,it,icf_sum(ix,iy,iz),im,2),
     &                  sum_fact)
        else
          sum_fact_r = 1.0d0 / sum_fact
          call invert_stdev(m,Xa,sigx,
     &                  tr_sum(ip,ie,it,icf_sum(ix,iy,iz),im,1),
     &                  tr_sum(ip,ie,it,icf_sum(ix,iy,iz),im,2),
     &                  sum_fact_r)
        endif
        tr_sum(ip,ie,it,icf_sum(ix,iy,iz),im,1) = Xa
        tr_sum(ip,ie,it,icf_sum(ix,iy,iz),im,2) = sigx

      else

        tr_sum(ip,ie,it,icf_sum(ix,iy,iz),im,2) = 0.0

      end if

      return
      end

************************************************************************
*                                                                      *
      subroutine  pwwgxyz_sumover_getput(mode,m,iax,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,nmstepi,
     &    ipi,iei,iti,ixi,iyi,izi,imi,maxtott,tott_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      real(8) :: tott_sum(maxtott,2)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

      real(8),pointer :: tr_sum(:)
      real(8),allocatable :: tott_in(:,:)
      character :: chin*200

      if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

         call pwwgxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,nmstepi,
     &    ipi,iei,iti,ixi,iyi,izi,imi,maxtott,tott_sum,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &    itmst_sum(m,iax),
     &    tr_sum)

       else
          tr_sum => trRES_sum(irestalm_sum(m,iax):)

          nsame = npstepi * nestepi * ntstepi * nxstepi
     &            nystepi * nzstepi * nmstepi
          allocate (tott_in(nsame,2))

          read(mode,'(a)') chin
          read(mode,'(26x,1000(1pe13.4,0pf8.4))')
     &    (tott_in(i,1),tott_in(i,2),i=1,nsame)

         call pwwgxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,nmstepi,
     &    ipi,iei,iti,ixi,iyi,izi,imi,nsame,tott_in,
     &    itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &    itxnm_sum(m,iax),itynm_sum(m,iax),itznm_sum(m,iax),
     &    itmst_sum(m,iax),
     &    tr_sum)

          deallocate (tott_in)

      endif

      return
      end

************************************************************************
*                                                                      *
      subroutine pwwgxyz_sumover_getput_sub(mode,
     &    npstepi,nestepi,ntstepi,nxstepi,nystepi,nzstepi,nmstepi,
     &    ipi,iei,iti,ixi,iyi,izi,imi,maxtott,tott_sum,
     &    np_sum,ne_sum,nt_sum,nx_sum,ny_sum,nz_sum,nm_sum,tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)

      real(8) :: tr_sum(np_sum,ne_sum,nt_sum,nx_sum*ny_sum*nz_sum,
     &                  nm_sum,2)

      real(8) :: tott_sum(maxtott,2)

      icf_sum(ix,iy,iz) = ix + ( iy - 1 ) * nx_sum
     &                  + ( iz - 1 ) * nx_sum * ny_sum

        i = 0
        do imloop=1,nmstepi
         do izloop=1,nzstepi
          do iyloop=1,nystepi
           do ixloop=1,nxstepi
            do itloop=1,ntstepi
              do ieloop=1,nestepi
                do iploop=1,npstepi
                  i = i + 1
                  do k=1,2
                   if(mode == 0) then
                     tott_sum(i,k) =
     &               tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &               icf_sum(ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1),
     &               imi+imloop-1,k)
                   else
                     tr_sum(ipi+iploop-1,iei+ieloop-1,iti+itloop-1,
     &               icf_sum(ixi+ixloop-1,iyi+iyloop-1,izi+izloop-1),
     &               imi+imloop-1,k)
     &               = tott_sum(i,k)
                   endif
                  enddo
                end do
              end do
            end do
          end do
         end do
        end do
       end do

      return
      end


************************************************************************
*                                                                      *
      subroutine tpointp_sumover(m,maxcas,
     &                   np,  ne, nt,  nr, nm, tr0x)
*                                                                      *
*     tr_sum(np,ne,nt,nr,nm,2)                                         *
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0

      implicit double precision (a-h,o-z)
      dimension   tr0x(np,ne,nt,nr,nm)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)


C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if
      if(n_tr_sum > 0) then

        call tpointp_sumover_sub(maxcas,itaxs(m,iax),
     &     np,  ne, nt, nr, nm,    tr0x,
     &     itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &     itmsh_sum(m,iax),itmst_sum(m,iax),
     &     tr_sum)

        endif

      enddo

      return
      end

************************************************************************
*                                                                      *
      subroutine tpointp_sumover_sub(maxcas,itaxs_in,
     &           np,  ne, nt, nr, nm, tr0,
     &           np_sum,  ne_sum, nt_sum, nr_sum, nm_sum,
     &           tr_sum)
*                                                                      *
************************************************************************

      implicit double precision (a-h,o-z)
      dimension   tr0(np,ne,nt,nr,nm)
      dimension   tr_sum(np_sum,ne_sum,nt_sum,nr_sum,nm_sum,2)

      if(itaxs_in == 1) then  ! energ
        do im = 1, nm
        do ir = 1, nr
        do it = 1, nt
        do ip = 1, np
          tr0_sum = 0.0d0
          do ie = 1, ne
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,im) / maxcas
          end do
          tr_sum(ip,1,it,ir,im,1) =
     &           tr_sum(ip,1,it,ir,im,1) + tr0_sum
          tr_sum(ip,1,it,ir,im,2) =
     &          tr_sum(ip,1,it,ir,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do
!
      elseif(itaxs_in == 2) then   ! time
        do im = 1, nm
        do ir = 1, nr
        do ie = 1, ne
        do ip = 1, np
          tr0_sum = 0.0d0
          do it = 1, nt
            tr0_sum = tr0_sum + tr0(ip,ie,it,ir,im) / maxcas
          end do
          tr_sum(ip,ie,1,ir,im,1) =
     &           tr_sum(ip,ie,1,ir,im,1) + tr0_sum
          tr_sum(ip,ie,1,ir,im,2) =
     &          tr_sum(ip,ie,1,ir,im,2) + tr0_sum ** 2
        end do
        end do
        end do
        end do

       end if
       return
       end


************************************************************************
*                                                                      *
      subroutine ptpointp_sumover_stdev(mode,m,ip,ie,it,ir,im,
     &                fact_in,ew,tw,ew_sum,tw_sum)
*                                                                      *
************************************************************************

      use TALMOD
!$      use TALMOD0
      use RESTALMOD

      implicit double precision (a-h,o-z)

      include 'param.inc'
      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tallsum/itpan_sum(itlmax,6),itenm_sum(itlmax,6),
     &                  ittnm_sum(itlmax,6),itrgn_sum(itlmax,6),
     &                  itmst_sum(itlmax,6),mftal_sum(itlmax,6),
     &                  itrnm_sum(itlmax,6),itanm_sum(itlmax,6),
     &                  itxnm_sum(itlmax,6),itynm_sum(itlmax,6),
     &                  itznm_sum(itlmax,6),itndy_sum(itlmax,6),
     &                  itndz_sum(itlmax,6),itndn_sum(itlmax,6),
     &                  itndm_sum(itlmax,6),itenm2_sum(itlmax,6),
     &                  itrcn_sum(itlmax,6),itactnm_sum(itlmax,6),
     &                  itmsh_sum(itlmax,6)

C for nonshared_tally option
      integer italsh
      common /talsh/ italsh

      real(8),pointer :: tr_sum(:)

      do iax=1,itaxn(m)

        if(mode == 0) then
C for nonshared_tally option
!$       if(italsh .eq. 0) then
!$          n_tr_sum = italsize0_sum(m,iax)
!$          call GET_TR_HEAD_POINTER0_SUM(tr_sum,m,iax)
!$       else
            n_tr_sum = italsize_sum(m,iax)
            call GET_TR_HEAD_POINTER_SUM(tr_sum,m,iax)
C for nonshared_tally option
!$       end if

        else
          n_tr_sum = italsize_sum(m,iax)
          tr_sum => trRES_sum(irestalm_sum(m,iax):)
        endif

        if(n_tr_sum > 0) then
          sum_fact = fact_in/ew/tw
          if(itaxs(m,iax) == 1 .and. ie == 1) then
             sum_fact = sum_fact * ew / ew_sum
          else if(itaxs(m,iax) == 2 .and. it == 1) then
             sum_fact = sum_fact * tw / tw_sum
          else
            sum_fact = 0.0d0
          endif
          if(sum_fact /= 0.0d0) then
            call ptpointp_sumover_stdev_sub(mode,m,sum_fact,
     &         ip,ie,it,ir,im,
     &         itpan_sum(m,iax),itenm_sum(m,iax),ittnm_sum(m,iax),
     &         itmsh_sum(m,iax),itmst_sum(m,iax),
     &         tr_sum)
          endif

        endif
      enddo

      return
      end

